-- M76 bounded stationary source candidate. Additive schema 19; historical methods remain unchanged.

-- M73 additive source-scoped synthetic natural-gas workpapers. M42/M71 remain intact.
create table neuvetra.stationary_diesel_heads(id uuid primary key,company_id uuid not null references neuvetra.companies(id),source_id uuid not null,asset_id text not null,version_id uuid,revision integer not null default 0,meter_key text,reference_key text,unique(id,company_id),unique(company_id,source_id),unique(company_id,meter_key),unique(company_id,reference_key));
create table neuvetra.stationary_diesel_statements(id uuid primary key,company_id uuid not null references neuvetra.companies(id),payload jsonb not null,statement_sha256 text not null,statement_text text not null,unique(id,company_id));
create table neuvetra.stationary_diesel_evidence_reservations(company_id uuid not null references neuvetra.companies(id),evidence_key text not null,worksheet_id uuid not null,kind text not null check(kind in('meter','reference')),created_at timestamptz not null,primary key(company_id,kind,evidence_key),foreign key(worksheet_id,company_id) references neuvetra.stationary_diesel_heads(id,company_id));
create table neuvetra.stationary_diesel_versions(id uuid primary key,company_id uuid not null,worksheet_id uuid not null,version integer not null,previous_version_id uuid,coverage_version_id uuid not null,statement_id uuid,quantity_gallons numeric(15,3),payload jsonb not null,input_sha256 text not null,content_sha256 text not null,version_sha256 text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null,export_text text not null,unique(id,company_id),unique(company_id,worksheet_id,version),foreign key(worksheet_id,company_id) references neuvetra.stationary_diesel_heads(id,company_id),foreign key(previous_version_id,company_id) references neuvetra.stationary_diesel_versions(id,company_id),foreign key(coverage_version_id,company_id) references neuvetra.corporate_inventory_versions(id,company_id),foreign key(statement_id,company_id) references neuvetra.stationary_diesel_statements(id,company_id));
alter table neuvetra.stationary_diesel_heads add foreign key(version_id,company_id) references neuvetra.stationary_diesel_versions(id,company_id);
create table neuvetra.stationary_diesel_reviews(id uuid primary key,company_id uuid not null,version_id uuid not null,payload jsonb not null,decision_sha256 text not null,reviewed_by uuid not null references auth.users(id),reviewed_at timestamptz not null,unique(id,company_id),unique(company_id,version_id),foreign key(version_id,company_id) references neuvetra.stationary_diesel_versions(id,company_id));
create table neuvetra.stationary_diesel_reports(id uuid primary key,company_id uuid not null,worksheet_id uuid not null,version_id uuid not null,decision_id uuid,payload jsonb not null,report_sha256 text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null,unique(id,company_id),foreign key(worksheet_id,company_id) references neuvetra.stationary_diesel_heads(id,company_id),foreign key(version_id,company_id) references neuvetra.stationary_diesel_versions(id,company_id),foreign key(decision_id,company_id) references neuvetra.stationary_diesel_reviews(id,company_id));
create unique index m76_diesel_report_state on neuvetra.stationary_diesel_reports(company_id,version_id,coalesce(decision_id,'00000000-0000-0000-0000-000000000000'::uuid));
create table neuvetra.stationary_diesel_requests(company_id uuid not null references neuvetra.companies(id),idempotency_key uuid not null,actor_id uuid not null references auth.users(id),kind text not null check(kind in('save','review','report')),fingerprint text not null,record_id uuid not null,primary key(company_id,idempotency_key));
create table neuvetra.stationary_diesel_audit(id uuid primary key,company_id uuid not null references neuvetra.companies(id),record_id uuid not null,kind text not null check(kind in('save','review','report')),record_sha256 text not null,actor_id uuid not null references auth.users(id),created_at timestamptz not null,unique(company_id,kind,record_id));
do $$declare t text;begin foreach t in array array['stationary_diesel_heads','stationary_diesel_evidence_reservations','stationary_diesel_statements','stationary_diesel_versions','stationary_diesel_reviews','stationary_diesel_reports','stationary_diesel_requests','stationary_diesel_audit'] loop
execute format('alter table neuvetra.%I enable row level security',t);execute format('alter table neuvetra.%I force row level security',t);execute format('revoke all on neuvetra.%I from public,authenticated,neuvetra_runtime',t);execute format('create policy m76_diesel_read on neuvetra.%I for select to neuvetra_runtime using(neuvetra.has_staging_access() and neuvetra.is_company_member(company_id))',t);execute format('grant select on neuvetra.%I to neuvetra_runtime',t);
if t<>'stationary_diesel_heads' then execute format('create trigger m76_diesel_immutable before update or delete on neuvetra.%I for each row execute function neuvetra.reject_inventory_history_mutation()',t);end if;end loop;end $$;


create function neuvetra.m76_diesel_validate_request(r jsonb)returns void language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare e jsonb:=r->'equipment';s jsonb:=r->'statement';k text;uuid_re text:='^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';begin
perform neuvetra.m71_keys(r,'profile,binding,period,equipment,unit,quantityGallons,statement,manualConfirmation,discrepancyReason,zeroReason,expectedVersionId,expectedVersionSha256,correctionReason,idempotencyKey');
if r->>'profile' is distinct from 'synthetic-stationary-diesel-v1' or r->'period' is distinct from '{"start":"2025-01-01","endExclusive":"2026-01-01"}'::jsonb or r->>'unit' is distinct from 'US_gallon' or jsonb_typeof(r->'manualConfirmation')is distinct from 'boolean' or jsonb_typeof(r->'idempotencyKey')is distinct from 'string' or r->>'idempotencyKey'!~uuid_re then raise exception 'invalid generator profile'using errcode='22023';end if;
perform neuvetra.m71_keys(e,'assetId,identifierBasis,equipmentType,engineType,stationaryInstallation,controlBasis,controlExplanation,fuel,fossilFraction,fuelGradeBasis');
if jsonb_typeof(e->'assetId')is distinct from 'string'or e->>'assetId'!~'^[A-Z0-9][A-Z0-9._-]{0,63}$'or e->>'equipmentType'is distinct from 'stationary_emergency_generator'or e->>'engineType'is distinct from 'compression_ignition'or e->>'stationaryInstallation'is distinct from 'fixed'or e->>'controlBasis'is distinct from 'owned_operational_control_full_year'or e->>'fuel'is distinct from 'Fossil Distillate Fuel Oil No. 2'or e->>'fossilFraction'is distinct from '1.000'then raise exception 'unsupported generator facts'using errcode='22023';end if;
foreach k in array array['identifierBasis','controlExplanation','fuelGradeBasis']loop perform neuvetra.m76_diesel_text(e->k,500);end loop;
foreach k in array array['discrepancyReason','zeroReason','correctionReason']loop if r->k<>'null'::jsonb then perform neuvetra.m76_diesel_text(r->k,500);end if;end loop;
if r->'expectedVersionId'='null'::jsonb then if r->'expectedVersionSha256'<>'null'::jsonb or r->'correctionReason'<>'null'::jsonb then raise exception 'invalid first generator binding'using errcode='22023';end if;else if jsonb_typeof(r->'expectedVersionId')is distinct from 'string'or r->>'expectedVersionId'!~uuid_re or jsonb_typeof(r->'expectedVersionSha256')is distinct from 'string'or r->>'expectedVersionSha256'!~'^[0-9a-f]{64}$'or r->'correctionReason'='null'::jsonb then raise exception 'invalid generator predecessor'using errcode='22023';end if;end if;
if r->'quantityGallons'<>'null'::jsonb then perform neuvetra.m76_diesel_quantity(r->'quantityGallons');end if;
if s<>'null'::jsonb then
perform neuvetra.m71_keys(s,'issuer,reference,meterLabel,statedQuantityGallons,description,consumptionBasis,measurementBasis,dedicatedToSingleDevice,includesTesting,stockDerivedConsumption,sharedFuelAllocation,consumptionBoundaryExplanation,supplierSpecificHhvAvailable,supplierSpecificCarbonAvailable,defaultFactorEligibilityExplanation');
foreach k in array array['issuer','reference','meterLabel']loop perform neuvetra.m76_diesel_text(s->k,120);end loop;
foreach k in array array['description','consumptionBoundaryExplanation','defaultFactorEligibilityExplanation']loop perform neuvetra.m76_diesel_text(s->k,2000);end loop;perform neuvetra.m76_diesel_quantity(s->'statedQuantityGallons');
if s->>'consumptionBasis'is distinct from 'dedicated_generator_consumed_no_adjustments'or s->>'measurementBasis'is distinct from 'direct_device_fuel_meter'or s->'dedicatedToSingleDevice'is distinct from 'true'::jsonb or s->'includesTesting'is distinct from 'true'::jsonb or s->'stockDerivedConsumption'is distinct from 'false'::jsonb or s->'sharedFuelAllocation'is distinct from 'false'::jsonb or s->'supplierSpecificHhvAvailable'is distinct from 'false'::jsonb or s->'supplierSpecificCarbonAvailable'is distinct from 'false'::jsonb then raise exception 'unsupported consumption/default evidence'using errcode='22023';end if;
if r->'quantityGallons'<>'null'::jsonb and r->>'quantityGallons'<>s->>'statedQuantityGallons'and r->'discrepancyReason'='null'::jsonb then raise exception 'explain unresolved discrepancy'using errcode='22023';end if;end if;end $$;

create function neuvetra.m76_diesel_text(v jsonb,maximum integer) returns text language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare s text:=v#>>'{}';begin if jsonb_typeof(v) is distinct from 'string' or length(s) not between 1 and maximum or s<>btrim(s) or s~U&'^[\00A0\1680\2000-\200A\2028\2029\202F\205F\3000\FEFF]|[\00A0\1680\2000-\200A\2028\2029\202F\205F\3000\FEFF]$' or s<>normalize(s,NFC) or s~'[[:cntrl:]]' then raise exception 'invalid text' using errcode='22023';end if;return s;end $$;

create function neuvetra.m76_diesel_quantity(v jsonb) returns text language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare s text:=v#>>'{}';begin if jsonb_typeof(v) is distinct from 'string' or s!~'^(0|[1-9][0-9]{0,11})\.[0-9]{3}$' then raise exception 'invalid quantity' using errcode='22023';end if;return s;end $$;

create function neuvetra.m76_diesel_exact(v numeric) returns text language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select case when position('.' in v::text)>0 then rtrim(rtrim(v::text,'0'),'.') else v::text end$$;

create function neuvetra.m76_diesel_display(v numeric) returns text language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$with x as(select v*10000 n),r as(select trunc(n) q,n-trunc(n) f from x) select to_char((q+case when f>0.5 or(f=0.5 and mod(q,2)=1)then 1 else 0 end)/10000,'FM999999999999999999999990.0000') from r$$;

create function neuvetra.m76_diesel_can_calculate(a jsonb) returns boolean language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select a->'quantityGallons'<>'null'::jsonb and a->'statement'<>'null'::jsonb and a->'manualConfirmation'='true'::jsonb and (case when a->>'quantityGallons'='0.000' then a#>>'{statement,statedQuantityGallons}'='0.000' and a->'zeroReason'<>'null'::jsonb else a->>'quantityGallons'=a#>>'{statement,statedQuantityGallons}' or a->'discrepancyReason'<>'null'::jsonb end)$$;

create function neuvetra.m76_diesel_activity_status(a jsonb) returns text language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select case when a->'quantityGallons'='null'::jsonb then 'missing' when a->'statement'='null'::jsonb then 'evidence_missing' when a->'manualConfirmation'<>'true'::jsonb then 'unconfirmed' when a->>'quantityGallons'<>a#>>'{statement,statedQuantityGallons}' then 'discrepancy' when a->>'quantityGallons'='0.000' then case when neuvetra.m76_diesel_can_calculate(a) then 'explicit_zero' else 'unsupported_zero' end else 'entered' end$$;

create function neuvetra.m76_diesel_findings(a jsonb) returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare out jsonb:='[{"code":"scope1_incomplete","message":"This generator subtotal does not cover all stationary, mobile, fugitive or process emissions."},{"code":"method_not_released","message":"Factors and method are development candidates; no reporting or assurance determination."}]';s text:=neuvetra.m76_diesel_activity_status(a);begin
if a->'quantityGallons'='null' then out:=out||'[{"code":"activity_missing","message":"Consumed U.S. gallons are missing; no emissions were calculated."}]';end if;
if a->'statement'='null' then out:=out||'[{"code":"statement_missing","message":"No synthetic consumed-fuel statement is retained."}]';end if;
if s='unconfirmed' then out:=out||'[{"code":"statement_unconfirmed","message":"The synthetic consumption evidence has not been manually confirmed."}]';end if;
if s='discrepancy' then out:=out||'[{"code":"activity_statement_discrepancy","message":"Entered and stated consumption differ; the discrepancy remains unresolved."}]';end if;
if a->>'quantityGallons'='0.000' and not neuvetra.m76_diesel_can_calculate(a) then out:=out||'[{"code":"unsupported_zero","message":"Zero needs matching zero evidence and a no-consumption rationale covering test and maintenance runs."}]';end if;return out;end $$;

create function neuvetra.m76_diesel_coverage(target_company uuid,b jsonb,current_required boolean default true) returns jsonb language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare cv record;s jsonb;e jsonb;f jsonb;src jsonb;bd jsonb;rel jsonb;node text;seen text[]:='{}';pair record;begin
perform neuvetra.m71_keys(b,'coverageVersionId,coverageVersionSha256,entityId,facilityId,sourceId,boundaryDecisionId');for pair in select key,value from jsonb_each(b) loop if jsonb_typeof(pair.value)<>'string' or (pair.value#>>'{}') !~ (case when pair.key='coverageVersionSha256' then '^[0-9a-f]{64}$' else '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' end) then raise exception 'invalid binding' using errcode='22023';end if;end loop;
select * into cv from neuvetra.corporate_inventory_versions where company_id=target_company and id=(b->>'coverageVersionId')::uuid;if not found or cv.version_sha256<>b->>'coverageVersionSha256' then raise exception 'coverage binding conflict' using errcode='23505';end if;
if current_required and not exists(select 1 from neuvetra.corporate_inventory_heads where company_id=target_company and version_id=cv.id) then raise exception 'coverage changed' using errcode='23505';end if;
s:=cv.payload->'snapshot';perform neuvetra.m71_snapshot(s,null);if neuvetra.m67_hash(s)<>cv.content_sha256 or neuvetra.m67_hash((cv.payload-'snapshot'-'versionSha256')||jsonb_build_object('profile','synthetic-corporate-coverage-v1'))<>cv.version_sha256 or cv.export_text<>neuvetra.m67_canonical(cv.payload||jsonb_build_object('findings',neuvetra.m71_findings(s),'synthetic',true,'corporateCompleteness','incomplete','releaseEligible',false,'assurance','none','emissionsTotals',null,'review',null)) then raise exception 'coverage integrity failure' using errcode='22023';end if;
select x into e from jsonb_array_elements(s->'entities')x where x->>'id'=b->>'entityId';select x into f from jsonb_array_elements(s->'facilities')x where x->>'id'=b->>'facilityId';select x into src from jsonb_array_elements(s->'sources')x where x->>'id'=b->>'sourceId';select x into bd from jsonb_array_elements(s->'boundaryDecisions')x where x->>'id'=b->>'boundaryDecisionId';
if s->>'consolidationApproach'<>'operational_control' or e is null or f is null or src is null or bd is null or src->>'domain'<>'stationary_combustion' or src->>'entityId'<>e->>'id' or src->>'facilityId'<>f->>'id' or f->>'entityId'<>e->>'id' or bd->>'entityId'<>e->>'id' or e->>'countryCode'<>'US' or e->>'regionCode' is distinct from 'CA' or f->>'countryCode'<>'US' or f->>'regionCode' is distinct from 'CA' or bd->>'disposition'<>'included_activity' or bd->'reason'='null' or jsonb_array_length(bd->'evidenceRefs')=0 then raise exception 'source ineligible' using errcode='22023';end if;
for pair in select value from jsonb_array_elements(jsonb_build_array(e,f,src,bd))loop if pair.value->>'start'<>'2025-01-01' or pair.value->>'endExclusive'<>'2026-01-01' then raise exception 'unsupported period' using errcode='22023';end if;end loop;
node:=e->>'id';loop if node=any(seen) then raise exception 'relationship cycle' using errcode='22023';end if;seen:=array_append(seen,node);select x into rel from jsonb_array_elements(s->'relationships')x where x->>'childEntityId'=node;exit when rel is null;if rel->>'start'<>'2025-01-01' or rel->>'endExclusive'<>'2026-01-01' or rel->>'ownershipPercent' is distinct from '100' or rel->'controlFacts'='null' or jsonb_array_length(rel->'evidenceRefs')=0 then raise exception 'control basis incomplete' using errcode='22023';end if;node:=rel->>'parentEntityId';end loop;
return cv.export_text::jsonb;end $$;

create function neuvetra.m76_diesel_statement(a jsonb,coverage jsonb) returns text language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare s jsonb:=coverage->'snapshot';e jsonb;f jsonb;src jsonb;begin select x into e from jsonb_array_elements(s->'entities')x where x->>'id'=a#>>'{binding,entityId}';select x into f from jsonb_array_elements(s->'facilities')x where x->>'id'=a#>>'{binding,facilityId}';select x into src from jsonb_array_elements(s->'sources')x where x->>'id'=a#>>'{binding,sourceId}';return 'SYNTHETIC — NOT AN ORIGINAL FUEL RECORD OR INDEPENDENT MEASUREMENT'||chr(10)||neuvetra.m67_canonical(jsonb_build_object('profile','m76-synthetic-generator-statement-v1','companyLabel',s->'companyLabel','entityLabel',e->'legalName','facilityLabel',f->'name','sourceLabel',src->'name','binding',a->'binding','period',a->'period','equipment',a->'equipment','unit',a->'unit','statement',a->'statement'))||chr(10);end $$;

create function neuvetra.m76_diesel_method() returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select '{"id":"m76.stationary-distillate-no2.ca2025.ar5.default-hhv.v1","version":"m76-development-v1","engineSha256":"60de93b901185527affd1eae73d400582cc9d041ecd13bb5668c9041374f6266","sourceSha256":"43afb91d79b2ae765b3a447549d9e1021a144a407cec5eb804be9fcf69a668a7","factorSha256":"7f2a655ff2fc3a214f8f076aeaf7acebc25a50f89801985f255157a3ab3a85d0","gwpSha256":"c151f9b90b23eba7ee9d36dd57a851ecf7a6f200c915579819b683d2b3b3c1c7","sourceTitle":"EPA GHG Emission Factors Hub 2025","sourceSheet":"Emission Factors Hub","factorCells":["C55","D55","E55","F55","G55"],"gwpCells":["E524","E525","E526"],"noteCells":["D14","D47:G47","C94","C95","C99","E523","C10","C556"],"hhvMmbtuPerGallon":"0.138","co2KgPerMmbtu":"73.96","ch4GramsPerMmbtu":"3.0","n2oGramsPerMmbtu":"0.60","ch4Gwp":"28","n2oGwp":"265","gwpAssessment":"IPCC AR5 100-year","status":"development_candidate_not_released","releaseEligible":false,"rights":"unresolved_for_factor_release"}'::jsonb$$;

create function neuvetra.m76_diesel_calculation(a jsonb,statement_hash text) returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare q numeric;co2 numeric;ch4 numeric;n2o numeric;total numeric;i jsonb;body jsonb;begin
if not neuvetra.m76_diesel_can_calculate(a) then return 'null'::jsonb;end if;q:=(a->>'quantityGallons')::numeric;co2:=q*0.138*73.96;ch4:=q*0.138*3*0.001;n2o:=q*0.138*0.60*0.001;total:=co2+ch4*28+n2o*265;
i:=jsonb_build_object('binding',a->'binding','period',a->'period','equipment',a->'equipment','unit',a->'unit','quantityGallons',a->'quantityGallons','statementSha256',statement_hash);
body:=jsonb_build_object('profile','m76-diesel-decimal-result-v1','input',i,'inputSha256',neuvetra.m67_hash(i),'method',neuvetra.m76_diesel_method(),'derivedHhv',jsonb_build_object('quantityMmbtu',neuvetra.m76_diesel_exact(q*0.138),'heatBasis','HHV','basis','default_hhv_estimate'),'gasResults',jsonb_build_object('co2',jsonb_build_object('mass',neuvetra.m76_diesel_exact(co2),'massUnit','kg CO2','co2e',neuvetra.m76_diesel_exact(co2),'co2eUnit','kg CO2e'),'ch4',jsonb_build_object('mass',neuvetra.m76_diesel_exact(ch4),'massUnit','kg CH4','co2e',neuvetra.m76_diesel_exact(ch4*28),'co2eUnit','kg CO2e'),'n2o',jsonb_build_object('mass',neuvetra.m76_diesel_exact(n2o),'massUnit','kg N2O','co2e',neuvetra.m76_diesel_exact(n2o*265),'co2eUnit','kg CO2e')),'total',jsonb_build_object('unrounded',neuvetra.m76_diesel_exact(total),'display',neuvetra.m76_diesel_display(total),'unit','kg CO2e','rounding','half_even_4dp'));
return body||jsonb_build_object('resultSha256',neuvetra.m67_hash(body));end $$;

create function neuvetra.m76_diesel_capacity(target_company uuid,new_bytes integer) returns void language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare used_bytes bigint;begin
select coalesce((select sum(octet_length(convert_to(export_text,'utf8'))+4096) from neuvetra.stationary_diesel_versions where company_id=target_company),0)+coalesce((select sum(octet_length(convert_to(payload::text,'utf8'))) from neuvetra.stationary_diesel_reports where company_id=target_company),0) into used_bytes;
if used_bytes+new_bytes>3800000 then raise exception 'history bytes limit' using errcode='54001';end if;end $$;

create function neuvetra.m76_diesel_escape(v text) returns text language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select replace(replace(replace(replace(replace(coalesce(v,'Missing'),'&','&amp;'),'<','&lt;'),'>','&gt;'),'"','&quot;'),chr(39),'&#39;')$$;

create function neuvetra.m76_diesel_pair(label text,v text) returns text language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select '<dt>'||label||'</dt><dd>'||neuvetra.m76_diesel_escape(v)||'</dd>'$$;

create function neuvetra.m76_diesel_render_report(snapshot jsonb) returns text language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare v jsonb:=snapshot->'version';a jsonb:=v->'activity';c jsonb:=v->'calculation';src jsonb;f jsonb;entity jsonb;facts text;results text;findings text;html text;begin
select x into src from jsonb_array_elements(v#>'{coverageVersion,snapshot,sources}') x where x->>'id'=a#>>'{binding,sourceId}';select x into f from jsonb_array_elements(v#>'{coverageVersion,snapshot,facilities}') x where x->>'id'=a#>>'{binding,facilityId}';select x into entity from jsonb_array_elements(v#>'{coverageVersion,snapshot,entities}') x where x->>'id'=a#>>'{binding,entityId}';
facts:='<dl>'||neuvetra.m76_diesel_pair('Company',v#>>'{coverageVersion,snapshot,companyLabel}')||neuvetra.m76_diesel_pair('Entity',entity->>'legalName')||neuvetra.m76_diesel_pair('Facility',f->>'name')||neuvetra.m76_diesel_pair('Source',src->>'name')||neuvetra.m76_diesel_pair('Equipment ID',a#>>'{equipment,assetId}')||neuvetra.m76_diesel_pair('Identifier basis',a#>>'{equipment,identifierBasis}')||neuvetra.m76_diesel_pair('Equipment type',a#>>'{equipment,equipmentType}')||neuvetra.m76_diesel_pair('Engine type',a#>>'{equipment,engineType}')||neuvetra.m76_diesel_pair('Installation',a#>>'{equipment,stationaryInstallation}')||neuvetra.m76_diesel_pair('Control basis',a#>>'{equipment,controlBasis}')||neuvetra.m76_diesel_pair('Control explanation',a#>>'{equipment,controlExplanation}')||neuvetra.m76_diesel_pair('Fuel',a#>>'{equipment,fuel}')||neuvetra.m76_diesel_pair('Fossil fraction',a#>>'{equipment,fossilFraction}')||neuvetra.m76_diesel_pair('Fuel grade basis',a#>>'{equipment,fuelGradeBasis}')||neuvetra.m76_diesel_pair('Period',(a#>>'{period,start}')||' to '||(a#>>'{period,endExclusive}'))||neuvetra.m76_diesel_pair('Entered consumed U.S. gallons',a->>'quantityGallons')||neuvetra.m76_diesel_pair('Stated consumed U.S. gallons',a#>>'{statement,statedQuantityGallons}')||neuvetra.m76_diesel_pair('Activity status',v->>'activityStatus')||neuvetra.m76_diesel_pair('Manual confirmation',a->>'manualConfirmation')||neuvetra.m76_diesel_pair('Issuer',a#>>'{statement,issuer}')||neuvetra.m76_diesel_pair('Reference',a#>>'{statement,reference}')||neuvetra.m76_diesel_pair('Meter',a#>>'{statement,meterLabel}')||neuvetra.m76_diesel_pair('Measurement basis',a#>>'{statement,measurementBasis}')||neuvetra.m76_diesel_pair('Consumption boundary explanation',a#>>'{statement,consumptionBoundaryExplanation}')||neuvetra.m76_diesel_pair('Default factor eligibility explanation',a#>>'{statement,defaultFactorEligibilityExplanation}')||neuvetra.m76_diesel_pair('Supplier-specific HHV available',a#>>'{statement,supplierSpecificHhvAvailable}')||neuvetra.m76_diesel_pair('Supplier-specific carbon available',a#>>'{statement,supplierSpecificCarbonAvailable}')||neuvetra.m76_diesel_pair('Includes test and maintenance runs',a#>>'{statement,includesTesting}')||neuvetra.m76_diesel_pair('Statement locator',v#>>'{statement,locator}')||neuvetra.m76_diesel_pair('Statement SHA-256',v#>>'{statement,sha256}')||neuvetra.m76_diesel_pair('Unresolved discrepancy explanation',a->>'discrepancyReason')||neuvetra.m76_diesel_pair('No-consumption explanation',a->>'zeroReason')||neuvetra.m76_diesel_pair('Derived HHV MMBtu',c#>>'{derivedHhv,quantityMmbtu}')||neuvetra.m76_diesel_pair('Exact source subtotal kg CO2e',c#>>'{total,unrounded}')||neuvetra.m76_diesel_pair('Displayed source subtotal kg CO2e',c#>>'{total,display}')||neuvetra.m76_diesel_pair('Method',c#>>'{method,id}')||neuvetra.m76_diesel_pair('Method version',c#>>'{method,version}')||neuvetra.m76_diesel_pair('Workbook SHA-256',c#>>'{method,sourceSha256}')||neuvetra.m76_diesel_pair('Factor locators',(select string_agg(x,', ' order by n) from jsonb_array_elements_text(c#>'{method,factorCells}') with ordinality x(x,n)))||neuvetra.m76_diesel_pair('GWP basis',c#>>'{method,gwpAssessment}')||neuvetra.m76_diesel_pair('Rights status',c#>>'{method,rights}')||neuvetra.m76_diesel_pair('Review as captured',coalesce(snapshot#>>'{review,decision}','Unreviewed'))||neuvetra.m76_diesel_pair('Reviewer note',snapshot#>>'{review,note}')||neuvetra.m76_diesel_pair('Correction reason',v->>'correctionReason')||'</dl>';
results:=case when c='null'::jsonb then '<p>No emissions total was calculated. Required compatible activity or evidence is missing, unconfirmed or contradictory.</p>' else '<table><thead><tr><th>Gas</th><th>Mass</th><th>kg CO2e</th></tr></thead><tbody>'||(select string_agg('<tr><th>'||upper(key)||'</th><td>'||neuvetra.m76_diesel_escape(c#>>array['gasResults',key,'mass'])||' '||neuvetra.m76_diesel_escape(c#>>array['gasResults',key,'massUnit'])||'</td><td>'||neuvetra.m76_diesel_escape(c#>>array['gasResults',key,'co2e'])||'</td></tr>','' order by n) from(values('co2',1),('ch4',2),('n2o',3)) gases(key,n))||'</tbody></table>' end;
findings:='<ul>'||(select coalesce(string_agg('<li>'||neuvetra.m76_diesel_escape(x->>'message')||'</li>','' order by n),'') from jsonb_array_elements(v->'findings') with ordinality x(x,n))||'</ul>';
return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src ''none''; style-src ''unsafe-inline''; base-uri ''none''; form-action ''none''"><title>Synthetic stationary generator source report</title><style>body{font:16px/1.5 system-ui;max-width:950px;margin:2rem auto;padding:0 1rem;color:#172f2c;overflow-wrap:anywhere}th,td{padding:.45rem;text-align:left;border-bottom:1px solid #ccd8d0}table{width:100%;border-collapse:collapse}pre{white-space:pre-wrap;font:13px/1.5 monospace}@media print{body{font-size:11pt;margin:0;max-width:none}h2{break-after:avoid}}</style></head><body><h1>Stationary generator subtotal — synthetic internal draft</h1><p>Development candidate. Factors and method are not released. Scope 1 and corporate inventory incomplete. No filing determination or external assurance.</p><h2>Equipment, consumption and evidence</h2>'||facts||'<h2>Gas results</h2>'||results||'<h2>Open findings</h2>'||findings||'<p>Consumed U.S. gallons are converted to HHV MMBtu using the default 0.138 MMBtu/gallon estimate because supplier-specific HHV and carbon data are unavailable. Gas masses and exact total retain computational precision. Only the displayed source subtotal is rounded to four decimals with half-even rounding. Combustion only; upstream emissions and other source families are excluded. No aggregate emissions.</p><details><summary>Exact version and provenance</summary><pre>'||neuvetra.m76_diesel_escape(neuvetra.m67_canonical(snapshot))||'</pre></details></body></html>';end $$;

create function neuvetra.m76_diesel_lock(target_company uuid,writing boolean) returns boolean language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$begin if not neuvetra.m71_lock(target_company,writing) then return false;end if;if writing then perform id from neuvetra.companies where id=target_company for update;perform id from neuvetra.corporate_inventory_heads where company_id=target_company for update;else perform id from neuvetra.companies where id=target_company for share;end if;return true;end $$;

create function neuvetra.save_stationary_diesel(target_company uuid,target_worksheet uuid,request jsonb,calculation jsonb) returns uuid language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare actor uuid:=auth.uid();head record;prior record;old record;coverage jsonb;a jsonb;statement jsonb:='null';statement_id uuid;statement_text text;statement_hash text;expected_calc jsonb;body jsonb;v jsonb;contributors jsonb;fingerprint text;input_hash text;content_hash text;version_hash text;frozen text;new_id uuid:=gen_random_uuid();captured timestamptz;meter text;ref text;begin
if not neuvetra.m71_lock(target_company,true) then raise exception 'forbidden' using errcode='42501';end if;perform id from neuvetra.companies where id=target_company for update;perform id from neuvetra.corporate_inventory_heads where company_id=target_company for update;
perform neuvetra.m76_diesel_validate_request(request);fingerprint:=neuvetra.m67_hash(jsonb_build_object('operation','save','actor',actor,'companyId',target_company,'worksheetId',target_worksheet,'request',request-'idempotencyKey'));
select * into old from neuvetra.stationary_diesel_requests where company_id=target_company and idempotency_key=(request->>'idempotencyKey')::uuid;if found then if old.fingerprint<>fingerprint or old.kind<>'save' or old.actor_id<>actor then raise exception 'idempotency conflict' using errcode='23505';end if;return old.record_id;end if;
coverage:=neuvetra.m76_diesel_coverage(target_company,request->'binding',true);a:=request-'expectedVersionId'-'expectedVersionSha256'-'correctionReason'-'idempotencyKey';
select * into head from neuvetra.stationary_diesel_heads where company_id=target_company and id=target_worksheet for update;
select * into prior from neuvetra.stationary_diesel_versions where company_id=target_company and id=head.version_id;
if target_worksheet is null then
if request->'expectedVersionId'<>'null' or exists(select 1 from neuvetra.stationary_diesel_heads where company_id=target_company and source_id=(a#>>'{binding,sourceId}')::uuid)then raise exception 'source stream exists' using errcode='23505';end if;
if(select count(*) from neuvetra.stationary_diesel_heads where company_id=target_company)>=1 then raise exception 'stream limit' using errcode='54000';end if;
insert into neuvetra.stationary_diesel_heads(id,company_id,source_id,asset_id) values(gen_random_uuid(),target_company,(a#>>'{binding,sourceId}')::uuid,a#>>'{equipment,assetId}') returning * into head;
else
if head.id is null then raise exception 'source identity conflict' using errcode='23505';end if;
select * into prior from neuvetra.stationary_diesel_versions where company_id=target_company and id=head.version_id;
if prior.id::text is distinct from request->>'expectedVersionId' or prior.version_sha256 is distinct from request->>'expectedVersionSha256' then raise exception 'stale source version' using errcode='23505';end if;
if prior.payload->'activity'=a then raise exception 'no-op correction' using errcode='23505';end if;end if;
if(select count(*) from neuvetra.stationary_diesel_versions where company_id=target_company)>=40 then raise exception 'version limit' using errcode='54000';end if;
if a->'statement'<>'null' then
statement_id:=gen_random_uuid();statement_text:=neuvetra.m76_diesel_statement(a,coverage);statement_hash:=encode(sha256(convert_to(statement_text,'utf8')),'hex');statement:=jsonb_build_object('id',statement_id,'profile','m76-synthetic-generator-statement-v1','input',a->'statement','locator','m76-diesel-statement:'||statement_id::text||':annual-activity','text',statement_text,'sha256',statement_hash,'byteLength',octet_length(convert_to(statement_text,'utf8')));
meter:=neuvetra.m67_hash(jsonb_build_array(lower(a#>>'{statement,issuer}'),lower(a#>>'{statement,meterLabel}'),'2025'));ref:=neuvetra.m67_hash(jsonb_build_array(lower(a#>>'{statement,issuer}'),lower(a#>>'{statement,reference}'),'2025'));
end if;
if meter is not null then
 if exists(select 1 from neuvetra.stationary_diesel_evidence_reservations where company_id=target_company and evidence_key in(meter,ref) and worksheet_id<>head.id) or exists(select 1 from neuvetra.mobile_diesel_evidence_reservations where company_id=target_company and evidence_key=ref and statement_kind='fuel') then raise exception 'consumed evidence conflict' using errcode='23505';end if;
 insert into neuvetra.stationary_diesel_evidence_reservations values(target_company,meter,head.id,'meter',clock_timestamp()) on conflict do nothing;
 insert into neuvetra.stationary_diesel_evidence_reservations values(target_company,ref,head.id,'reference',clock_timestamp()) on conflict do nothing;
 end if;
expected_calc:=neuvetra.m76_diesel_calculation(a,statement_hash);if calculation is distinct from expected_calc then raise exception 'calculation binding invalid' using errcode='22023';end if;
-- This update also enforces same company/meter/year and issuer/reference/year uniqueness.
update neuvetra.stationary_diesel_heads set meter_key=meter,reference_key=ref,source_id=(a#>>'{binding,sourceId}')::uuid,asset_id=a#>>'{equipment,assetId}' where id=head.id;
captured:=date_trunc('milliseconds',clock_timestamp());
select jsonb_agg(x order by x collate "C") into contributors from(select distinct x from(select jsonb_array_elements_text(coalesce(prior.payload->'contributorIds','[]'))x union all select jsonb_array_elements_text(coverage->'contributorIds') union all select actor::text)a)a;
input_hash:=neuvetra.m67_hash(a);body:=jsonb_build_object('activity',a,'activityStatus',neuvetra.m76_diesel_activity_status(a),'coverageVersion',coverage,'statement',statement,'calculation',calculation,'findings',neuvetra.m76_diesel_findings(a));content_hash:=neuvetra.m67_hash(body);
v:=jsonb_build_object('profile','synthetic-stationary-diesel-v1','id',new_id,'companyId',target_company,'worksheetId',head.id,'version',head.revision+1,'previousVersionId',prior.id,'previousVersionSha256',prior.version_sha256,'createdBy',actor,'createdAt',to_char(captured at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'contributorIds',contributors,'correctionReason',request->'correctionReason','inputSha256',input_hash,'contentSha256',content_hash);version_hash:=neuvetra.m67_hash(v);
v:=(v-'profile')||body||jsonb_build_object('versionSha256',version_hash,'synthetic',true,'scope1Completeness','incomplete','corporateCompleteness','incomplete','releaseEligible',false,'assurance','none','review',null);frozen:=neuvetra.m67_canonical(v);
if octet_length(convert_to(frozen,'utf8'))>102400 then raise exception 'version bytes limit' using errcode='54001';end if;perform neuvetra.m76_diesel_capacity(target_company,octet_length(convert_to(frozen,'utf8'))+4096);
if statement_id is not null then insert into neuvetra.stationary_diesel_statements values(statement_id,target_company,statement,statement_hash,statement_text);end if;
insert into neuvetra.stationary_diesel_versions values(new_id,target_company,head.id,head.revision+1,prior.id,(a#>>'{binding,coverageVersionId}')::uuid,statement_id,(a->>'quantityGallons')::numeric,v,input_hash,content_hash,version_hash,actor,captured,frozen);
insert into neuvetra.stationary_diesel_requests values(target_company,(request->>'idempotencyKey')::uuid,actor,'save',fingerprint,new_id);insert into neuvetra.stationary_diesel_audit values(gen_random_uuid(),target_company,new_id,'save',version_hash,actor,captured);
update neuvetra.stationary_diesel_heads set version_id=new_id,revision=revision+1 where id=head.id;return new_id;end $$;

create function neuvetra.review_stationary_diesel(target_company uuid,target_worksheet uuid,request jsonb) returns uuid language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare actor uuid:=auth.uid();v record;old record;body jsonb;fingerprint text;digest text;new_id uuid:=gen_random_uuid();captured timestamptz;pair record;begin
if not neuvetra.m71_lock(target_company,true) then raise exception 'forbidden' using errcode='42501';end if;perform id from neuvetra.companies where id=target_company for update;perform id from neuvetra.corporate_inventory_heads where company_id=target_company for update;perform id from neuvetra.stationary_diesel_heads where company_id=target_company and id=target_worksheet for update;
perform neuvetra.m71_keys(request,'versionId,expectedVersionSha256,decision,note,acknowledgedLimitations,idempotencyKey');for pair in select key,value from jsonb_each(request) where key<>'acknowledgedLimitations'loop if jsonb_typeof(pair.value)<>'string' then raise exception 'invalid review type' using errcode='22023';end if;end loop;
if request->>'versionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or request->>'idempotencyKey'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or request->>'expectedVersionSha256'!~'^[0-9a-f]{64}$' or request->>'decision' not in('accepted_bounded_internal','changes_requested') or request->'acknowledgedLimitations'<>'["synthetic_only","scope1_incomplete","corporate_inventory_incomplete","factor_and_method_not_released","stationary_generator_subtotal_only","default_hhv_estimate","combustion_only_upstream_excluded","requirements_not_determined","no_external_assurance"]'::jsonb then raise exception 'invalid review' using errcode='22023';end if;perform neuvetra.m76_diesel_text(request->'note',500);
fingerprint:=neuvetra.m67_hash(jsonb_build_object('operation','review','actor',actor,'companyId',target_company,'worksheetId',target_worksheet,'request',request-'idempotencyKey'));select * into old from neuvetra.stationary_diesel_requests where company_id=target_company and idempotency_key=(request->>'idempotencyKey')::uuid;if found then if old.fingerprint<>fingerprint or old.kind<>'review' or old.actor_id<>actor then raise exception 'idempotency conflict' using errcode='23505';end if;return old.record_id;end if;
select * into v from neuvetra.stationary_diesel_versions where company_id=target_company and worksheet_id=target_worksheet and id=(request->>'versionId')::uuid;if not found or v.version_sha256<>request->>'expectedVersionSha256' or not exists(select 1 from neuvetra.stationary_diesel_heads where id=target_worksheet and version_id=v.id) then raise exception 'stale review version' using errcode='23505';end if;
if v.payload->'contributorIds'?actor::text then raise exception 'contributor cannot review' using errcode='42501';end if;perform neuvetra.m76_diesel_coverage(target_company,v.payload#>'{activity,binding}',true);if request->>'decision'='accepted_bounded_internal' and (v.payload->'calculation'='null' or exists(select 1 from jsonb_array_elements(v.payload->'findings') f where f->>'code' not in('scope1_incomplete','method_not_released'))) then raise exception 'missing calculation' using errcode='22023';end if;
captured:=date_trunc('milliseconds',clock_timestamp());body:=jsonb_build_object('id',new_id,'versionId',v.id,'versionSha256',v.version_sha256,'decision',request->'decision','note',request->'note','acknowledgedLimitations',request->'acknowledgedLimitations','reviewerId',actor,'reviewedAt',to_char(captured at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));digest:=neuvetra.m67_hash(body||jsonb_build_object('profile','synthetic-stationary-diesel-v1','companyId',target_company));body:=body||jsonb_build_object('decisionSha256',digest);
insert into neuvetra.stationary_diesel_reviews values(new_id,target_company,v.id,body,digest,actor,captured);insert into neuvetra.stationary_diesel_requests values(target_company,(request->>'idempotencyKey')::uuid,actor,'review',fingerprint,new_id);insert into neuvetra.stationary_diesel_audit values(gen_random_uuid(),target_company,new_id,'review',digest,actor,captured);return new_id;end $$;

create function neuvetra.create_stationary_diesel_report(target_company uuid,target_worksheet uuid,request jsonb) returns uuid language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare actor uuid:=auth.uid();v record;decision record;old record;new_id uuid:=gen_random_uuid();captured timestamptz;fingerprint text;snapshot jsonb;snapshot_text text;html text;body jsonb;digest text;begin
if not neuvetra.m71_lock(target_company,true) then raise exception 'forbidden' using errcode='42501';end if;perform id from neuvetra.companies where id=target_company for update;perform id from neuvetra.corporate_inventory_heads where company_id=target_company for update;perform id from neuvetra.stationary_diesel_heads where company_id=target_company and id=target_worksheet for update;
perform neuvetra.m71_keys(request,'versionId,expectedVersionSha256,expectedDecisionId,expectedDecisionSha256,idempotencyKey');
if jsonb_typeof(request->'versionId')<>'string' or request->>'versionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or jsonb_typeof(request->'idempotencyKey')<>'string' or request->>'idempotencyKey'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or jsonb_typeof(request->'expectedVersionSha256')<>'string' or request->>'expectedVersionSha256'!~'^[0-9a-f]{64}$' then raise exception 'invalid report request' using errcode='22023';end if;
if request->'expectedDecisionId'='null' then if request->'expectedDecisionSha256'<>'null' then raise exception 'invalid decision pair' using errcode='23505';end if;else if jsonb_typeof(request->'expectedDecisionId')<>'string' or request->>'expectedDecisionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or jsonb_typeof(request->'expectedDecisionSha256')<>'string' or request->>'expectedDecisionSha256'!~'^[0-9a-f]{64}$' then raise exception 'invalid decision pair' using errcode='23505';end if;end if;
fingerprint:=neuvetra.m67_hash(jsonb_build_object('operation','report','actor',actor,'companyId',target_company,'worksheetId',target_worksheet,'request',request-'idempotencyKey'));select * into old from neuvetra.stationary_diesel_requests where company_id=target_company and idempotency_key=(request->>'idempotencyKey')::uuid;if found then if old.fingerprint<>fingerprint or old.kind<>'report' or old.actor_id<>actor then raise exception 'idempotency conflict' using errcode='23505';end if;return old.record_id;end if;
select * into v from neuvetra.stationary_diesel_versions where company_id=target_company and worksheet_id=target_worksheet and id=(request->>'versionId')::uuid;if not found or v.version_sha256<>request->>'expectedVersionSha256' then raise exception 'report version conflict' using errcode='23505';end if;perform neuvetra.m76_diesel_coverage(target_company,v.payload#>'{activity,binding}',true);
select * into decision from neuvetra.stationary_diesel_reviews where company_id=target_company and version_id=v.id;
if decision.id::text is distinct from request->>'expectedDecisionId' or decision.decision_sha256 is distinct from request->>'expectedDecisionSha256' then raise exception 'actual decision does not match report pin' using errcode='23505';end if;
if(select count(*) from neuvetra.stationary_diesel_reports where company_id=target_company)>=40 then raise exception 'report history limit' using errcode='54000';end if;
snapshot:=jsonb_build_object('profile','m76-generator-source-report-v1','version',v.payload,'review',decision.payload);snapshot_text:=neuvetra.m67_canonical(snapshot);html:=neuvetra.m76_diesel_render_report(snapshot);if octet_length(convert_to(html,'utf8'))>131072 then raise exception 'report bytes limit' using errcode='54001';end if;
captured:=date_trunc('milliseconds',clock_timestamp());body:=jsonb_build_object('id',new_id,'companyId',target_company,'worksheetId',target_worksheet,'versionId',v.id,'versionSha256',v.version_sha256,'decisionId',decision.id,'decisionSha256',decision.decision_sha256,'createdBy',actor,'createdAt',to_char(captured at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'rendererVersion','m76-generator-source-report-v1','htmlSha256',encode(sha256(convert_to(html,'utf8')),'hex'),'htmlByteLength',octet_length(convert_to(html,'utf8')),'snapshotSha256',encode(sha256(convert_to(snapshot_text,'utf8')),'hex'));
digest:=neuvetra.m67_hash(body||jsonb_build_object('profile','synthetic-stationary-diesel-v1'));body:=body||jsonb_build_object('html',html,'snapshotJson',snapshot_text,'reportSha256',digest);perform neuvetra.m76_diesel_capacity(target_company,octet_length(convert_to(body::text,'utf8')));
insert into neuvetra.stationary_diesel_reports values(new_id,target_company,target_worksheet,v.id,decision.id,body,digest,actor,captured);insert into neuvetra.stationary_diesel_requests values(target_company,(request->>'idempotencyKey')::uuid,actor,'report',fingerprint,new_id);insert into neuvetra.stationary_diesel_audit values(gen_random_uuid(),target_company,new_id,'report',digest,actor,captured);return new_id;end $$;

-- Additive synthetic controlled-fleet roster and reconciliation reports.
create table neuvetra.stationary_equipment_heads(company_id uuid primary key references neuvetra.companies(id),id uuid not null,version_id uuid,revision integer not null default 0,unique(id,company_id));
create table neuvetra.stationary_equipment_statements(id uuid primary key,company_id uuid not null references neuvetra.companies(id),payload jsonb not null,statement_sha256 text not null,statement_text text not null,unique(id,company_id));
create table neuvetra.stationary_equipment_versions(id uuid primary key,company_id uuid not null,roster_id uuid not null,version integer not null,previous_version_id uuid,coverage_version_id uuid not null,statement_id uuid,payload jsonb not null,input_sha256 text not null,content_sha256 text not null,version_sha256 text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null,export_text text not null,unique(id,company_id),unique(company_id,roster_id,version),foreign key(roster_id,company_id) references neuvetra.stationary_equipment_heads(id,company_id),foreign key(previous_version_id,company_id) references neuvetra.stationary_equipment_versions(id,company_id),foreign key(coverage_version_id,company_id) references neuvetra.corporate_inventory_versions(id,company_id),foreign key(statement_id,company_id) references neuvetra.stationary_equipment_statements(id,company_id));
alter table neuvetra.stationary_equipment_heads add constraint stationary_equipment_head_version_fk foreign key(version_id,company_id) references neuvetra.stationary_equipment_versions(id,company_id) deferrable initially deferred;
create table neuvetra.stationary_equipment_reviews(id uuid primary key,company_id uuid not null,version_id uuid not null,payload jsonb not null,decision_sha256 text not null,reviewed_by uuid not null references auth.users(id),reviewed_at timestamptz not null,unique(id,company_id),unique(company_id,version_id),foreign key(version_id,company_id) references neuvetra.stationary_equipment_versions(id,company_id));
create table neuvetra.stationary_equipment_reports(id uuid primary key,company_id uuid not null,roster_id uuid not null,version_id uuid not null,payload jsonb not null,report_sha256 text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null,unique(id,company_id),foreign key(roster_id,company_id) references neuvetra.stationary_equipment_heads(id,company_id),foreign key(version_id,company_id) references neuvetra.stationary_equipment_versions(id,company_id));
create table neuvetra.stationary_equipment_requests(company_id uuid not null references neuvetra.companies(id),idempotency_key uuid not null,actor_id uuid not null references auth.users(id),kind text not null check(kind in('save','review','report')),fingerprint text not null,record_id uuid not null,primary key(company_id,idempotency_key));
create table neuvetra.stationary_equipment_audit(id uuid primary key,company_id uuid not null references neuvetra.companies(id),record_id uuid not null,kind text not null check(kind in('save','review','report')),record_sha256 text not null,actor_id uuid not null references auth.users(id),created_at timestamptz not null,unique(company_id,kind,record_id));

do $$declare t text;begin foreach t in array array['stationary_equipment_heads','stationary_equipment_statements','stationary_equipment_versions','stationary_equipment_reviews','stationary_equipment_reports','stationary_equipment_requests','stationary_equipment_audit'] loop execute format('alter table neuvetra.%I enable row level security',t);execute format('alter table neuvetra.%I force row level security',t);execute format('revoke all on neuvetra.%I from public,authenticated,neuvetra_runtime',t);execute format('create policy m76_read on neuvetra.%I for select to neuvetra_runtime using(neuvetra.has_staging_access() and neuvetra.is_company_member(company_id))',t);execute format('grant select on neuvetra.%I to neuvetra_runtime',t);if t<>'stationary_equipment_heads' then execute format('create trigger m76_immutable before update or delete on neuvetra.%I for each row execute function neuvetra.reject_inventory_history_mutation()',t);end if;end loop;end $$;



create function neuvetra.m76_activity_valid(a jsonb)returns boolean language plpgsql immutable set search_path=pg_catalog,neuvetra as $$declare s jsonb:=a->'rosterStatement';e jsonb;r jsonb;l jsonb;k text;ids jsonb;uuid_re text:='^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';id_re text:='^[A-Z0-9][A-Z0-9._-]{0,63}$';date_re text:='^[0-9]{4}-[0-9]{2}-[0-9]{2}$';begin
if not neuvetra.m76_exact_keys(a,array['profile','coverageVersionId','coverageVersionSha256','period','rosterStatement','manualConfirmation','links'])or a->>'profile'is distinct from 'synthetic-stationary-equipment-v1'or a->>'coverageVersionId'!~uuid_re or a->>'coverageVersionSha256'!~'^[0-9a-f]{64}$'or a->'period'is distinct from '{"start":"2025-01-01","endExclusive":"2026-01-01"}'::jsonb or jsonb_typeof(a->'manualConfirmation')is distinct from 'boolean'or jsonb_typeof(a->'links')is distinct from 'array'or jsonb_array_length(a->'links')>25 then return false;end if;
if s='null'::jsonb then return a->'links'='[]'::jsonb;end if;
if not neuvetra.m76_exact_keys(s,array['issuer','reference','description','discoveryBasis','coveredEntityIds','coveredFacilityIds','completeness','allControlledLocationsIncluded','assets'])or not neuvetra.m76_text_valid(s->'issuer',120)or not neuvetra.m76_text_valid(s->'reference',120)or not neuvetra.m76_text_valid(s->'description',2000)or not neuvetra.m76_text_valid(s->'discoveryBasis',2000)or s->>'completeness'not in('declared_complete','partial','unknown')or jsonb_typeof(s->'allControlledLocationsIncluded')is distinct from 'boolean'or jsonb_typeof(s->'assets')is distinct from 'array'or jsonb_array_length(s->'assets')>25 then return false;end if;
foreach k in array array['coveredEntityIds','coveredFacilityIds']loop ids:=s->k;if jsonb_typeof(ids)is distinct from 'array'or exists(select 1 from jsonb_array_elements(ids)x where jsonb_typeof(x)<>'string'or x#>>'{}'!~uuid_re)or ids is distinct from(select coalesce(jsonb_agg(x order by x#>>'{}'collate "C"),'[]')from(select distinct x from jsonb_array_elements(ids)x)q)then return false;end if;end loop;
for e in select x from jsonb_array_elements(s->'assets')x loop
if not neuvetra.m76_exact_keys(e,array['rowId','equipmentId','aliases','identifierBasis','entityId','facilityId','period','equipmentType','fuel','controlBasis','classificationBasis','controlExplanation','meterRelationship'])or e->>'rowId'!~uuid_re or(e->'equipmentId'<>'null'::jsonb and(jsonb_typeof(e->'equipmentId')<>'string'or e->>'equipmentId'!~id_re))or jsonb_typeof(e->'aliases')is distinct from 'array'or jsonb_array_length(e->'aliases')>8 or e->>'equipmentType'not in('boiler','space_heater','stationary_emergency_generator','other','unknown')or e->>'controlBasis'not in('owned_operational_control_full_year','other_control_arrangement','unknown')then return false;end if;
foreach k in array array['entityId','facilityId']loop if e->k<>'null'::jsonb and(jsonb_typeof(e->k)<>'string'or e->>k!~uuid_re)then return false;end if;end loop;
foreach k in array array['identifierBasis','classificationBasis','controlExplanation']loop if e->k<>'null'::jsonb and not neuvetra.m76_text_valid(e->k,500)then return false;end if;end loop;if e->'fuel'<>'null'::jsonb and not neuvetra.m76_text_valid(e->'fuel',100)then return false;end if;
if exists(select 1 from jsonb_array_elements(e->'aliases')x where jsonb_typeof(x)<>'string'or x#>>'{}'!~id_re or x=e->'equipmentId')or e->'aliases'is distinct from(select coalesce(jsonb_agg(x order by x#>>'{}'collate "C"),'[]')from(select distinct x from jsonb_array_elements(e->'aliases')x)q)then return false;end if;
r:=e->'period';if r<>'null'::jsonb then if not neuvetra.m76_exact_keys(r,array['start','endExclusive'])or r->>'start'!~date_re or r->>'endExclusive'!~date_re or to_char(to_date(r->>'start','FXYYYY-MM-DD'),'YYYY-MM-DD')<>r->>'start'or to_char(to_date(r->>'endExclusive','FXYYYY-MM-DD'),'YYYY-MM-DD')<>r->>'endExclusive'or r->>'start'>=r->>'endExclusive'then return false;end if;end if;
r:=e->'meterRelationship';if r<>'null'::jsonb then if not neuvetra.m76_exact_keys(r,array['issuer','meterLabel','measurementBasis','dedicatedToSingleDevice','explanation'])or r->>'measurementBasis'not in('dedicated_single_device_consumption','shared_meter','shared_tank_allocation','stock_derived','other','unknown')or r->'dedicatedToSingleDevice'not in('null'::jsonb,'true'::jsonb,'false'::jsonb)then return false;end if;foreach k in array array['issuer','meterLabel']loop if r->k<>'null'::jsonb and not neuvetra.m76_text_valid(r->k,120)then return false;end if;end loop;if r->'explanation'<>'null'::jsonb and not neuvetra.m76_text_valid(r->'explanation',2000)then return false;end if;end if;end loop;
if(select count(*)from jsonb_array_elements(s->'assets'))<>(select count(distinct x->>'rowId')from jsonb_array_elements(s->'assets')x)then return false;end if;
for l in select x from jsonb_array_elements(a->'links')x loop if not neuvetra.m76_exact_keys(l,array['rowId','sourceId'])or l->>'rowId'!~uuid_re or(l->'sourceId'<>'null'::jsonb and(jsonb_typeof(l->'sourceId')<>'string'or l->>'sourceId'!~uuid_re))then return false;end if;end loop;
return(select count(*)from jsonb_array_elements(a->'links'))=(select count(distinct x->>'rowId')from jsonb_array_elements(a->'links')x)and(select jsonb_agg(x->'rowId'order by x->>'rowId')from jsonb_array_elements(a->'links')x)is not distinct from(select jsonb_agg(x->'rowId'order by x->>'rowId')from jsonb_array_elements(s->'assets')x);
exception when others then return false;end $$;

create function neuvetra.m76_lock(target_company uuid,writing boolean) returns boolean language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$begin if not neuvetra.m71_lock(target_company,writing) then return false;end if;if writing then perform id from neuvetra.companies where id=target_company for update;perform id from neuvetra.corporate_inventory_heads where company_id=target_company for update;perform id from neuvetra.stationary_equipment_heads where company_id=target_company for update;perform id from neuvetra.stationary_gas_heads where company_id=target_company order by id for update;perform id from neuvetra.stationary_diesel_heads where company_id=target_company order by id for update;else perform id from neuvetra.companies where id=target_company for share;end if;return true;end $$;

create function neuvetra.m76_exact_keys(value jsonb, expected text[]) returns boolean language sql immutable set search_path=pg_catalog as $$select jsonb_typeof(value)='object' and (select coalesce(array_agg(k order by k),'{}'::text[]) from jsonb_object_keys(value) k)=(select coalesce(array_agg(k order by k),'{}'::text[]) from unnest(expected) k)$$;

create function neuvetra.m76_text_valid(value jsonb,max_chars integer) returns boolean language sql immutable set search_path=pg_catalog as $$select jsonb_typeof(value)='string' and length(btrim(value#>>'{}')) between 1 and max_chars and value#>>'{}'=btrim(value#>>'{}') and normalize(value#>>'{}',NFC)=value#>>'{}' and value#>>'{}'!~'[\u0000-\u001F\u007F-\u009F]'$$;

create function neuvetra.m76_current_workpapers(target_company uuid) returns jsonb language sql stable security definer set search_path=pg_catalog,neuvetra,pg_temp as $$select coalesce(jsonb_agg(p order by p->>'_family' collate "C",p->>'worksheetId' collate "C"),'[]') from(
select v.payload||jsonb_build_object('review',r.payload,'_family','natural_gas') p from neuvetra.stationary_gas_heads h join neuvetra.stationary_gas_versions v on v.id=h.version_id and v.company_id=h.company_id left join neuvetra.stationary_gas_reviews r on r.version_id=v.id and r.company_id=v.company_id where h.company_id=target_company
union all select v.payload||jsonb_build_object('review',r.payload,'_family','stationary_diesel') from neuvetra.stationary_diesel_heads h join neuvetra.stationary_diesel_versions v on v.id=h.version_id and v.company_id=h.company_id left join neuvetra.stationary_diesel_reviews r on r.version_id=v.id and r.company_id=v.company_id where h.company_id=target_company)q$$;

create function neuvetra.m76_dependencies(coverage jsonb,workpapers jsonb) returns jsonb language sql immutable set search_path=pg_catalog,neuvetra as $$with pins as(select coalesce(jsonb_agg(jsonb_build_object('family',w->'_family','worksheetId',w->'worksheetId','sourceId',w#>'{activity,binding,sourceId}','equipmentId',case when w->>'_family'='stationary_diesel' then w#>'{activity,equipment,assetId}' else 'null'::jsonb end,'version',jsonb_build_object('id',w->'id','sha256',w->'versionSha256'),'decision',case when coalesce(w->'review','null'::jsonb)='null'::jsonb then 'null'::jsonb else jsonb_build_object('id',w#>'{review,id}','sha256',w#>'{review,decisionSha256}')end) order by w->>'_family' collate "C",w->>'worksheetId' collate "C"),'[]')p from jsonb_array_elements(workpapers)w),body as(select jsonb_build_object('coveragePin',case when coalesce(coverage,'null'::jsonb)='null'::jsonb then 'null'::jsonb else jsonb_build_object('id',coverage->'id','sha256',coverage->'versionSha256')end,'coverageReviewPin',case when coalesce(coverage->'review','null'::jsonb)='null'::jsonb then 'null'::jsonb else jsonb_build_object('id',coverage#>'{review,id}','sha256',coverage#>'{review,decisionSha256}')end,'workpaperPins',p)b from pins)select b||jsonb_build_object('dependencySha256',neuvetra.m67_hash(b))from body$$;

create function neuvetra.m76_current_dependencies(target_company uuid) returns jsonb language sql stable security definer set search_path=pg_catalog,neuvetra,pg_temp as $$select neuvetra.m76_dependencies((select v.payload||jsonb_build_object('review',r.payload)from neuvetra.corporate_inventory_heads h join neuvetra.corporate_inventory_versions v on v.id=h.version_id and v.company_id=h.company_id left join neuvetra.corporate_inventory_reviews r on r.version_id=v.id and r.company_id=v.company_id where h.company_id=target_company),neuvetra.m76_current_workpapers(target_company))$$;

create function neuvetra.m76_f(code text,row_key text,message text) returns jsonb language sql immutable set search_path=pg_catalog as $$select jsonb_build_array(jsonb_build_object('code',code,'rowKey',row_key,'message',message,'blocking',true))$$;

create function neuvetra.m76_roster_findings(activity jsonb,coverage jsonb) returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra as $$
#variable_conflict use_column
declare out jsonb:='[]';s jsonb:=activity->'rosterStatement';a jsonb;m jsonb;source_id text;key text;expected jsonb;dupe record;row_id text;begin
if s='null'::jsonb then return neuvetra.m76_f('roster_statement_missing',null,'The independently declared stationary-equipment statement is missing.');end if;
if activity->'manualConfirmation'<>'true'::jsonb then out:=out||neuvetra.m76_f('roster_unconfirmed',null,'Confirm the synthetic equipment declaration.');end if;
if jsonb_array_length(s->'assets')=0 then out:=out||neuvetra.m76_f('roster_empty',null,'An empty declaration cannot establish zero stationary equipment.');end if;
if s->>'completeness'<>'declared_complete' then out:=out||neuvetra.m76_f('roster_not_declared_complete',null,'The equipment population is partial or unknown.');end if;
if s->'allControlledLocationsIncluded'<>'true'::jsonb then out:=out||neuvetra.m76_f('controlled_locations_incomplete',null,'The declaration must cover all controlled locations.');end if;
select coalesce(jsonb_agg(x->'id' order by x->>'id' collate "C"),'[]')into expected from jsonb_array_elements(coverage#>'{snapshot,entities}')x;
if s->'coveredEntityIds' is distinct from expected then out:=out||neuvetra.m76_f('entity_population_incomplete',null,'Every corporate entity needs an equipment population declaration.');end if;
select coalesce(jsonb_agg(x->'id' order by x->>'id' collate "C"),'[]')into expected from jsonb_array_elements(coverage#>'{snapshot,facilities}')x;
if s->'coveredFacilityIds' is distinct from expected then out:=out||neuvetra.m76_f('facility_population_incomplete',null,'Every corporate facility needs an equipment population declaration.');end if;
for a in select x from jsonb_array_elements(s->'assets') with ordinality t(x,n)order by n loop key:='roster:'||(a->>'rowId');m:=a->'meterRelationship';select l->>'sourceId'into source_id from jsonb_array_elements(activity->'links')l where l->>'rowId'=a->>'rowId';
if a->>'equipmentId' is null then out:=out||neuvetra.m76_f('equipment_identity_unknown',key,'Stable physical equipment identity is unknown.');end if;
if a->>'entityId' is null or a->>'facilityId' is null or a->'period'='null'::jsonb or a->>'equipmentType'='unknown' or a->>'fuel' is null or a->>'controlBasis'='unknown' or a->>'identifierBasis' is null or a->>'classificationBasis' is null or a->>'controlExplanation' is null then out:=out||neuvetra.m76_f('equipment_facts_unknown',key,'Required identity, facility, period, classification, fuel or control facts are unknown.');end if;
if a->>'entityId' is not null and not exists(select 1 from jsonb_array_elements(coverage#>'{snapshot,entities}')e where e->>'id'=a->>'entityId') then out:=out||neuvetra.m76_f('unknown_entity',key,'The declared entity is absent from bound corporate coverage.');end if;
if a->>'facilityId' is not null and not exists(select 1 from jsonb_array_elements(coverage#>'{snapshot,facilities}')e where e->>'id'=a->>'facilityId' and e->>'entityId'=a->>'entityId') then out:=out||neuvetra.m76_f('facility_conflict',key,'The declared facility is absent or belongs to another entity.');end if;
if source_id is not null and not exists(select 1 from jsonb_array_elements(coverage#>'{snapshot,sources}')e where e->>'id'=source_id and e->>'domain'='stationary_combustion') then out:=out||neuvetra.m76_f('source_conflict',key,'The mapped source is absent or is not stationary combustion.');end if;
if source_id is null then out:=out||neuvetra.m76_f('source_missing',key,'No corporate stationary source is mapped to this equipment.');end if;
if m->>'issuer' is null or m->>'meterLabel' is null or m->>'explanation' is null or m->>'measurementBasis'='unknown' or m->'dedicatedToSingleDevice'='null'::jsonb then out:=out||neuvetra.m76_f('meter_relationship_unknown',key,'Dedicated consumption evidence identity or relationship is unknown.');end if;
if m<>'null'::jsonb and(m->>'measurementBasis'<>'dedicated_single_device_consumption' or m->'dedicatedToSingleDevice'<>'true'::jsonb) and m->>'measurementBasis'<>'unknown' then out:=out||neuvetra.m76_f('meter_relationship_unsupported',key,'Shared, allocated, stock-derived or other evidence relationships remain unsupported.');end if;
if a->>'equipmentId' is not null and a->>'equipmentType'<>'unknown' and a->>'fuel' is not null and a->>'controlBasis'<>'unknown' and a->'period'<>'null'::jsonb and (not((a->>'equipmentType' in('boiler','space_heater')and a->>'fuel'='Natural Gas')or(a->>'equipmentType'='stationary_emergency_generator'and a->>'fuel'='Fossil Distillate Fuel Oil No. 2'))or a->>'controlBasis'<>'owned_operational_control_full_year' or a->'period'<>'{"start":"2025-01-01","endExclusive":"2026-01-01"}'::jsonb) then out:=out||neuvetra.m76_f('equipment_profile_unsupported',key,'The declared equipment, fuel, period or control is outside the current stationary candidate profile.');end if;
end loop;
for dupe in with identities as(select a->>'equipmentId' id,a->>'rowId' row_id,n*10 pos from jsonb_array_elements(s->'assets') with ordinality x(a,n)where a->>'equipmentId' is not null union all select alias#>>'{}',a->>'rowId',n*10+k from jsonb_array_elements(s->'assets') with ordinality x(a,n)cross join lateral jsonb_array_elements(a->'aliases') with ordinality y(alias,k))select id,array_agg(row_id order by pos)rows from identities group by id having count(*)>1 order by min(pos)loop foreach row_id in array dupe.rows loop out:=out||neuvetra.m76_f('duplicate_equipment_identity','roster:'||row_id,'Physical identity '||dupe.id||' appears in multiple equipment rows.');end loop;end loop;
for dupe in select l->>'sourceId' id,array_agg(a->>'rowId'order by n)rows from jsonb_array_elements(s->'assets')with ordinality x(a,n)join jsonb_array_elements(activity->'links')l on l->>'rowId'=a->>'rowId'where l->>'sourceId' is not null group by l->>'sourceId' having count(*)>1 order by min(n)loop foreach row_id in array dupe.rows loop out:=out||neuvetra.m76_f('duplicate_source_mapping','roster:'||row_id,'Stationary source '||dupe.id||' maps to multiple equipment rows.');end loop;end loop;
for dupe in select array_agg(a->>'rowId'order by n)rows from jsonb_array_elements(s->'assets')with ordinality x(a,n)where a#>>'{meterRelationship,issuer}' is not null and a#>>'{meterRelationship,meterLabel}'is not null group by lower(a#>>'{meterRelationship,issuer}'),lower(a#>>'{meterRelationship,meterLabel}'),a->'period' having count(*)>1 order by min(n)loop foreach row_id in array dupe.rows loop out:=out||neuvetra.m76_f('duplicate_meter_relationship','roster:'||row_id,'The same dedicated meter-period is claimed for multiple equipment rows.');end loop;end loop;
return out;end $$;

create function neuvetra.m76_html_escape(value text) returns text language sql immutable set search_path=pg_catalog as $$select replace(replace(replace(replace(replace(coalesce(value,''),'&','&amp;'),'<','&lt;'),'>','&gt;'),'"','&quot;'),'''','&#39;')$$;

create function neuvetra.m76_render_report(snapshot jsonb) returns text language sql immutable set search_path=pg_catalog,neuvetra as $$with r as(select snapshot->'version' v,snapshot->'review' review,snapshot->'reconciliation' reconciliation),parts as(select '<p class="'||case when reconciliation->>'status'='blocked' then 'blocked' else '' end||'"><strong>'||neuvetra.m76_html_escape(case when reconciliation->>'status'='blocked' then 'Blocked — open findings remain' else 'Declared synthetic stationary devices reconciled to current internally reviewed workpapers' end)||'</strong></p><p>Company '||neuvetra.m76_html_escape(reconciliation->>'companyId')||' · '||neuvetra.m76_html_escape(reconciliation#>>'{period,start}')||' to '||neuvetra.m76_html_escape(reconciliation#>>'{period,endExclusive}')||' · roster version '||neuvetra.m76_html_escape(v->>'version')||'. Equipment review: '||neuvetra.m76_html_escape(coalesce(review->>'decision','unreviewed'))||'.</p><p>No emissions aggregation. Candidate factors and methods are not released. Scope 1 and the corporate inventory remain incomplete. Requirements are not determined. No external assurance.</p>' summary,case when v->'statement'='null'::jsonb then '<p class="blocked">Roster statement missing.</p>' else '<dl><dt>Locator</dt><dd>'||neuvetra.m76_html_escape(v#>>'{statement,locator}')||'</dd><dt>SHA-256</dt><dd>'||neuvetra.m76_html_escape(v#>>'{statement,sha256}')||'</dd><dt>Issuer / reference</dt><dd>'||neuvetra.m76_html_escape(v#>>'{statement,input,issuer}')||' / '||neuvetra.m76_html_escape(v#>>'{statement,input,reference}')||'</dd><dt>Declaration</dt><dd>'||neuvetra.m76_html_escape(v#>>'{statement,input,completeness}')||' · all controlled locations '||case when v#>>'{statement,input,allControlledLocationsIncluded}'='true' then 'included' else 'not confirmed' end||'</dd></dl>' end evidence,coalesce((select string_agg('<tr><td>'||neuvetra.m76_html_escape(coalesce(x->>'rosterRowId','—'))||'</td><td>'||neuvetra.m76_html_escape(coalesce(x->>'equipmentId','unknown'))||'</td><td>'||neuvetra.m76_html_escape(coalesce(x->>'sourceId','—'))||'<br>'||coalesce((select string_agg(neuvetra.m76_html_escape(w#>>'{}'),'<br>' order by n) from jsonb_array_elements(x->'worksheetIds') with ordinality q(w,n)),'—')||'</td><td>'||neuvetra.m76_html_escape(x->>'status')||'</td><td>'||coalesce((select string_agg(neuvetra.m76_html_escape(f->>'message'),'<br>' order by n) from jsonb_array_elements(x->'findings') with ordinality q(f,n)),'—')||'</td></tr>','' order by n) from jsonb_array_elements(reconciliation->'rows') with ordinality q(x,n)),'') rows,case when jsonb_array_length(reconciliation->'findings')=0 then '<p>No reconciliation blockers.</p>' else '<ul>'||(select string_agg('<li>'||neuvetra.m76_html_escape(f->>'code')||': '||neuvetra.m76_html_escape(f->>'message')||'</li>','' order by n) from jsonb_array_elements(reconciliation->'findings') with ordinality q(f,n))||'</ul>' end findings,'<ul>'||(select string_agg('<li>'||neuvetra.m76_html_escape(x#>>'{}')||'</li>','' order by n) from jsonb_array_elements(reconciliation->'limitations') with ordinality q(x,n))||'</ul>' limitations from r) select '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src ''none''; style-src ''unsafe-inline''; base-uri ''none''; form-action ''none''"><title>Synthetic stationary reconciliation</title><style>body{font:16px/1.5 system-ui;margin:2rem auto;padding:0 1rem;max-width:1000px;color:#172f2c;overflow-wrap:anywhere}h1,h2{line-height:1.2}table{border-collapse:collapse;width:100%}th,td{padding:.45rem;text-align:left;vertical-align:top;border-bottom:1px solid #ccd8d0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.5 monospace;background:#f3f6f3;padding:1rem}.blocked{color:#8a281f}@media print{body{font-size:10pt;margin:0;max-width:none}h2{break-after:avoid}tr{break-inside:avoid}}</style></head><body><h1>Stationary equipment reconciliation — synthetic internal draft</h1>'||summary||'<h2>Declared roster evidence</h2>'||evidence||'<h2>Full reconciliation union</h2><table><thead><tr><th>Roster row</th><th>Asset</th><th>Source / workpaper</th><th>Status</th><th>Findings</th></tr></thead><tbody>'||rows||'</tbody></table><h2>Open findings</h2>'||findings||'<h2>Limitations</h2>'||limitations||'<details><summary>Exact snapshot</summary><pre>'||neuvetra.m76_html_escape(neuvetra.m67_canonical(snapshot))||'</pre></details></body></html>' from parts$$;

create function neuvetra.m76_source_eligible(coverage jsonb, source jsonb) returns boolean
language plpgsql immutable set search_path=pg_catalog as $$
declare entity jsonb; facility jsonb; boundary jsonb; relationship jsonb; current_id text; seen text[]:='{}'; item jsonb;
begin
select e into entity from jsonb_array_elements(coverage#>'{snapshot,entities}') e where e->>'id'=source->>'entityId' limit 1;
select f into facility from jsonb_array_elements(coverage#>'{snapshot,facilities}') f where f->>'id'=source->>'facilityId' limit 1;
select b into boundary from jsonb_array_elements(coverage#>'{snapshot,boundaryDecisions}') with ordinality x(b,n) where b->>'entityId'=source->>'entityId' and b->>'start'='2025-01-01' and b->>'endExclusive'='2026-01-01' order by n limit 1;
if coverage#>>'{snapshot,consolidationApproach}' is distinct from 'operational_control' or entity is null or facility is null or facility->>'entityId' is distinct from entity->>'id' or entity->>'countryCode' is distinct from 'US' or entity->>'regionCode' is distinct from 'CA' or facility->>'countryCode' is distinct from 'US' or facility->>'regionCode' is distinct from 'CA' then return false; end if;
foreach item in array array[coverage#>'{snapshot,period}',entity,facility,source] loop
 if item->>'start' is distinct from '2025-01-01' or item->>'endExclusive' is distinct from '2026-01-01' then return false; end if;
end loop;

if boundary is null or boundary->>'disposition' is distinct from 'included_activity' or nullif(btrim(boundary->>'reason'),'') is null or not exists(select 1 from jsonb_array_elements(boundary->'evidenceRefs') r where r->>'artifactId'='71000000-0000-4000-8000-000000000900' and r->>'expectedSha256'='4fe7dc12d8f253f8d3cb1fd7fba2eade05f3d605ad7cb95376cca9d957afe5c7' and r->>'locator'='synthetic-register:entities-and-screening') then return false;end if;
current_id:=entity->>'id';while current_id is not null and current_id<>'' loop
 if current_id=any(seen) then return false;end if;seen:=array_append(seen,current_id);
 select r into relationship from jsonb_array_elements(coverage#>'{snapshot,relationships}') with ordinality x(r,n) where r->>'childEntityId'=current_id order by n limit 1;
 if relationship is null then exit;end if;
if relationship->>'start' is distinct from '2025-01-01' or relationship->>'endExclusive' is distinct from '2026-01-01' or relationship->>'ownershipPercent' is distinct from '100' or nullif(btrim(relationship->>'controlFacts'),'') is null or not exists(select 1 from jsonb_array_elements(relationship->'evidenceRefs') r where r->>'artifactId'='71000000-0000-4000-8000-000000000900' and r->>'expectedSha256'='4fe7dc12d8f253f8d3cb1fd7fba2eade05f3d605ad7cb95376cca9d957afe5c7' and r->>'locator'='synthetic-register:entities-and-screening') then return false;end if;
 current_id:=relationship->>'parentEntityId';
end loop;return true;end $$;

create function neuvetra.m76_row_status(findings jsonb) returns text language plpgsql immutable set search_path=pg_catalog as $$
declare codes text[]; code text;
begin select coalesce(array_agg(f->>'code'),'{}') into codes from jsonb_array_elements(findings) f where f->>'blocking'='true';
if exists(select 1 from unnest(codes) c where left(c,10)='duplicate_') then return 'duplicate';end if;
if exists(select 1 from unnest(codes)c where position('unsupported'in c)>0 or c='workpaper_family_conflict') then return 'unsupported';end if;
if exists(select 1 from unnest(codes) c where position('unknown' in c)>0 or position('unconfirmed' in c)>0) then return 'unknown';end if;
if 'orphan_source'=any(codes) then return 'orphan_source';end if;
if 'orphan_workpaper'=any(codes) then return 'orphan_workpaper';end if;
if 'source_missing'=any(codes) then return 'missing_source';end if;
if exists(select 1 from unnest(codes) c where position('stale' in c)>0) then return 'stale';end if;
if 'capacity_blocked'=any(codes) then return 'capacity_blocked';end if;
if 'workpaper_missing'=any(codes) then return 'missing_workpaper';end if;
if cardinality(codes)>0 then return 'workpaper_incomplete';end if;
return 'matched_reviewed';end $$;

create function neuvetra.m76_derive_reconciliation(target_company uuid,coverage jsonb,workpapers jsonb,version_payload jsonb,reviews jsonb)
returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra as $$
declare
 deps jsonb; pins jsonb; global_findings jsonb:='[]'; rows_json jsonb:='[]'; all_findings jsonb;
 activity jsonb:=version_payload->'activity'; statement jsonb:=activity->'rosterStatement';
 sources jsonb; source jsonb; asset jsonb; head jsonb; works jsonb; findings jsonb; screening jsonb;
 row_key text; source_id text; worksheet_ids jsonb; mapped_sources text[]:='{}'; used_worksheets text[]:='{}';
 entity_label text; facility_label text; current_review jsonb; final_status text; base jsonb;
begin
deps:=neuvetra.m76_dependencies(coverage,workpapers);

if coverage#>>'{review,decision}' is distinct from 'accepted_bounded_internal' then global_findings:=global_findings||jsonb_build_array(jsonb_build_object('code','coverage_review_required','rowKey',null,'message','The exact current corporate coverage version needs bounded internal acceptance.','blocking',true)); end if;
if coalesce(version_payload,'null'::jsonb)='null'::jsonb then global_findings:=global_findings||jsonb_build_array(jsonb_build_object('code','roster_missing','rowKey',null,'message','No independent stationary-equipment declaration has been saved.','blocking',true)); else
 global_findings:=global_findings||(version_payload->'findings');
if version_payload#>>'{dependencies,dependencySha256}' is distinct from deps->>'dependencySha256' then global_findings:=global_findings||jsonb_build_array(jsonb_build_object('code','dependency_stale','rowKey',null,'message','Corporate coverage or a stationary workpaper/review changed; save a current declaration successor.','blocking',true)); end if;
if activity->>'coverageVersionId' is distinct from coverage->>'id' or activity->>'coverageVersionSha256' is distinct from coverage->>'versionSha256' then global_findings:=global_findings||jsonb_build_array(jsonb_build_object('code','coverage_stale','rowKey',null,'message','The declaration is not bound to current corporate coverage.','blocking',true)); end if;
end if;
select coalesce(jsonb_agg(s order by n),'[]') into sources from jsonb_array_elements(coverage#>'{snapshot,sources}') with ordinality x(s,n) where s->>'domain'='stationary_combustion';
for asset in select a from jsonb_array_elements(coalesce(statement->'assets','[]'::jsonb)) with ordinality x(a,n) order by n loop
 row_key:='roster:'||(asset->>'rowId');
 select coalesce(jsonb_agg(f order by n),'[]') into findings from jsonb_array_elements(version_payload->'findings') with ordinality x(f,n) where f->>'rowKey'=row_key;
 select l->>'sourceId' into source_id from jsonb_array_elements(activity->'links') with ordinality x(l,n) where l->>'rowId'=asset->>'rowId' order by n desc limit 1;
 select s into source from jsonb_array_elements(sources) s where s->>'id'=source_id limit 1;
 select coalesce(jsonb_agg(w order by n),'[]') into works from jsonb_array_elements(workpapers) with ordinality x(w,n) where w#>>'{activity,binding,sourceId}'=source_id;
 if source_id is not null then mapped_sources:=array_append(mapped_sources,source_id);end if;
 for head in select w from jsonb_array_elements(works) w loop used_worksheets:=array_append(used_worksheets,head->>'worksheetId');end loop;
if source_id is not null and source is null then findings:=findings||jsonb_build_array(jsonb_build_object('code','source_missing','rowKey',row_key,'message','The mapped stationary source is absent from current corporate coverage.','blocking',true)); end if;
if source is not null and neuvetra.m76_source_eligible(coverage,source) is not true then findings:=findings||jsonb_build_array(jsonb_build_object('code','source_ineligible','rowKey',row_key,'message','The corporate stationary source or boundary is not eligible for the candidate.','blocking',true)); end if;
if source is not null then
 select s into screening from jsonb_array_elements(coverage#>'{snapshot,coverageItems}') with ordinality x(s,n) where s->>'sourceId'=source->>'id' and s->>'domain'='stationary_combustion' order by n limit 1;
if screening is null or screening->>'disposition' is distinct from 'included_activity' then findings:=findings||jsonb_build_array(jsonb_build_object('code','source_screening_unresolved','rowKey',row_key,'message','Current stationary-source screening must be included activity; missing, estimate, excluded or not-applicable assertions remain unresolved.','blocking',true)); end if;
end if;
if jsonb_array_length(works)=0 and source is not null then if (asset->>'equipmentType' in('boiler','space_heater') and asset->>'fuel'='Natural Gas' and(select count(*)from jsonb_array_elements(workpapers)w where w->>'_family'='natural_gas')>=3) or(asset->>'equipmentType'='stationary_emergency_generator'and asset->>'fuel'='Fossil Distillate Fuel Oil No. 2' and(select count(*)from jsonb_array_elements(workpapers)w where w->>'_family'='stationary_diesel')>=1)then findings:=findings||jsonb_build_array(jsonb_build_object('code','capacity_blocked','rowKey',row_key,'message','The relevant stationary workpaper capacity is full.','blocking',true)); else findings:=findings||jsonb_build_array(jsonb_build_object('code','workpaper_missing','rowKey',row_key,'message','No current compatible stationary workpaper exists for this equipment.','blocking',true)); end if;end if;
if jsonb_array_length(works)>1 then findings:=findings||jsonb_build_array(jsonb_build_object('code','duplicate_workpaper','rowKey',row_key,'message','Multiple effective workpapers, including cross-family records, map to this stationary source.','blocking',true)); end if;
for head in select w from jsonb_array_elements(works) with ordinality x(w,n) order by n loop
if head->>'_family' is distinct from(case when asset->>'equipmentType' in('boiler','space_heater')and asset->>'fuel'='Natural Gas' then 'natural_gas' when asset->>'equipmentType'='stationary_emergency_generator'and asset->>'fuel'='Fossil Distillate Fuel Oil No. 2' then 'stationary_diesel' else null end)then findings:=findings||neuvetra.m76_f('workpaper_family_conflict',row_key,'Declared equipment/fuel and workpaper family differ.');end if;
if asset->'entityId' is distinct from head#>'{activity,binding,entityId}' or asset->'facilityId' is distinct from head#>'{activity,binding,facilityId}' or asset->>'controlBasis'<>'owned_operational_control_full_year' or asset->'period' is distinct from head#>'{activity,period}'then findings:=findings||neuvetra.m76_f('workpaper_fact_conflict',row_key,'Equipment and workpaper entity, facility, control or period differ.');end if;
if head->>'_family'='stationary_diesel' and(asset->'equipmentId' is distinct from head#>'{activity,equipment,assetId}'or asset->'identifierBasis' is distinct from head#>'{activity,equipment,identifierBasis}'or asset->'equipmentType' is distinct from head#>'{activity,equipment,equipmentType}'or asset->'fuel' is distinct from head#>'{activity,equipment,fuel}'or asset->'controlBasis' is distinct from head#>'{activity,equipment,controlBasis}'or asset->'controlExplanation' is distinct from head#>'{activity,equipment,controlExplanation}')then findings:=findings||neuvetra.m76_f('workpaper_equipment_conflict',row_key,'Generator equipment identity, fuel or control facts differ from the declaration.');end if;
if head#>'{activity,statement}'='null'::jsonb or asset#>>'{meterRelationship,issuer}'is null or asset#>>'{meterRelationship,meterLabel}'is null or lower(head#>>'{activity,statement,issuer}')is distinct from lower(asset#>>'{meterRelationship,issuer}')or lower(head#>>'{activity,statement,meterLabel}')is distinct from lower(asset#>>'{meterRelationship,meterLabel}')then findings:=findings||neuvetra.m76_f('workpaper_meter_conflict',row_key,'Declared consumption evidence issuer/meter and retained workpaper evidence differ.');end if;
if coalesce(head->'calculation','null'::jsonb)='null'::jsonb or exists(select 1 from jsonb_array_elements(head->'findings')f where f->>'code'not in('scope1_incomplete','method_not_released'))then findings:=findings||neuvetra.m76_f('workpaper_incomplete',row_key,'Current workpaper activity/evidence is missing, discrepant, unsupported or unconfirmed.');end if;
if head#>>'{activity,binding,coverageVersionId}' is distinct from coverage->>'id' or head#>>'{activity,binding,coverageVersionSha256}' is distinct from coverage->>'versionSha256' then findings:=findings||jsonb_build_array(jsonb_build_object('code','workpaper_stale','rowKey',row_key,'message','The current workpaper is bound to older corporate coverage.','blocking',true)); end if;
if head#>>'{review,decision}' is distinct from 'accepted_bounded_internal' then findings:=findings||jsonb_build_array(jsonb_build_object('code','workpaper_review_required','rowKey',row_key,'message','The exact current stationary workpaper needs separate bounded internal acceptance.','blocking',true)); end if;
end loop;
select coalesce(jsonb_agg(w->'worksheetId' order by (w->>'worksheetId') collate "C"),'[]') into worksheet_ids from jsonb_array_elements(works) w;
select e->>'legalName' into entity_label from jsonb_array_elements(coverage#>'{snapshot,entities}') e where e->>'id'=asset->>'entityId' limit 1;
select f->>'name' into facility_label from jsonb_array_elements(coverage#>'{snapshot,facilities}') f where f->>'id'=asset->>'facilityId' limit 1;
rows_json:=rows_json||jsonb_build_array(jsonb_build_object('rowKey',row_key,'rosterRowId',asset->'rowId','sourceId',source_id,'equipmentId',asset->'equipmentId','worksheetIds',worksheet_ids,'entityLabel',entity_label,'facilityLabel',facility_label,'sourceLabel',source->>'name','status',neuvetra.m76_row_status(findings),'findings',findings));
end loop;
for source in select s from jsonb_array_elements(sources) with ordinality x(s,n) where not(s->>'id'=any(mapped_sources)) order by n loop
 row_key:='source:'||(source->>'id');findings:='[]';
findings:=findings||jsonb_build_array(jsonb_build_object('code','orphan_source','rowKey',row_key,'message','Current corporate stationary source is absent from the equipment declaration.','blocking',true));
 select coalesce(jsonb_agg(w order by n),'[]') into works from jsonb_array_elements(workpapers) with ordinality x(w,n) where w#>>'{activity,binding,sourceId}'=source->>'id';
 for head in select w from jsonb_array_elements(works) w loop used_worksheets:=array_append(used_worksheets,head->>'worksheetId');end loop;
if jsonb_array_length(works)>1 then findings:=findings||neuvetra.m76_f('duplicate_workpaper',row_key,'Multiple current workpaper families map to this stationary source.');end if;
 select coalesce(jsonb_agg(w->'worksheetId' order by (w->>'worksheetId') collate "C"),'[]') into worksheet_ids from jsonb_array_elements(works) w;
 select e->>'legalName' into entity_label from jsonb_array_elements(coverage#>'{snapshot,entities}') e where e->>'id'=source->>'entityId' limit 1;
 select f->>'name' into facility_label from jsonb_array_elements(coverage#>'{snapshot,facilities}') f where f->>'id'=source->>'facilityId' limit 1;
 rows_json:=rows_json||jsonb_build_array(jsonb_build_object('rowKey',row_key,'rosterRowId',null,'sourceId',source->'id','equipmentId',null,'worksheetIds',worksheet_ids,'entityLabel',entity_label,'facilityLabel',facility_label,'sourceLabel',source->>'name','status','orphan_source','findings',findings));
end loop;
for head in select w from jsonb_array_elements(workpapers) with ordinality x(w,n) where not(w->>'worksheetId'=any(used_worksheets)) order by n loop
 row_key:='workpaper:'||(head->>'worksheetId');findings:='[]';
findings:=findings||jsonb_build_array(jsonb_build_object('code','orphan_workpaper','rowKey',row_key,'message','Current stationary workpaper is absent from the equipment declaration/source mapping.','blocking',true));
 rows_json:=rows_json||jsonb_build_array(jsonb_build_object('rowKey',row_key,'rosterRowId',null,'sourceId',head#>'{activity,binding,sourceId}','equipmentId',case when head->>'_family'='stationary_diesel' then head#>'{activity,equipment,assetId}'else 'null'::jsonb end,'worksheetIds',jsonb_build_array(head->'worksheetId'),'entityLabel',null,'facilityLabel',null,'sourceLabel',null,'status','orphan_workpaper','findings',findings));
end loop;
select coalesce(jsonb_agg(r order by (r->>'rowKey') collate "C"),'[]') into rows_json from jsonb_array_elements(rows_json) r;
select global_findings||coalesce(jsonb_agg(f order by n,k),'[]') into all_findings from jsonb_array_elements(rows_json) with ordinality x(r,n) cross join lateral jsonb_array_elements(r->'findings') with ordinality y(f,k);
select r into current_review from jsonb_array_elements(reviews) with ordinality x(r,n) where r->>'versionId'=version_payload->>'id' and r->>'versionSha256'=version_payload->>'versionSha256' and r#>>'{dependencies,dependencySha256}'=deps->>'dependencySha256' order by n limit 1;
if current_review is null or current_review->>'decision' is distinct from 'accepted_bounded_reconciliation' then all_findings:=all_findings||jsonb_build_array(jsonb_build_object('code','roster_review_required','rowKey',null,'message','The exact current stationary reconciliation needs independent internal acceptance.','blocking',true)); end if;
final_status:=case when not exists(select 1 from jsonb_array_elements(all_findings) f where f->>'blocking'='true' and f->>'code'<>'roster_review_required') and current_review->>'decision'='accepted_bounded_reconciliation' then 'reconciled_bounded_synthetic' else 'blocked' end;
base:=jsonb_build_object('profile','m76-stationary-reconciliation-v1','companyId',target_company,'period',jsonb_build_object('start','2025-01-01','endExclusive','2026-01-01'),
'rosterPin',case when coalesce(version_payload,'null'::jsonb)='null'::jsonb then 'null'::jsonb else jsonb_build_object('id',version_payload->'id','sha256',version_payload->'versionSha256') end,
'rosterReviewPin',case when current_review is null then 'null'::jsonb else jsonb_build_object('id',current_review->'id','sha256',current_review->'decisionSha256') end,
'coveragePin',deps->'coveragePin','coverageReviewPin',deps->'coverageReviewPin','workpaperPins',deps->'workpaperPins','rows',rows_json,'findings',all_findings,
'counts',jsonb_build_object('evidenceRows',jsonb_array_length(coalesce(statement->'assets','[]'::jsonb)),
'declaredUniqueKnownEquipment',(select count(distinct a->>'equipmentId') from jsonb_array_elements(coalesce(statement->'assets','[]'::jsonb)) a where nullif(a->>'equipmentId','') is not null),
'currentStationarySources',jsonb_array_length(sources),'currentWorkpaperStreams',jsonb_array_length(workpapers),
'reconciledRows',(select count(*) from jsonb_array_elements(rows_json) r where r->>'status'='matched_reviewed'),
'blockingFindings',(select count(*) from jsonb_array_elements(all_findings) f where f->>'blocking'='true')),
'status',final_status,'dependencySha256',deps->>'dependencySha256',
'limitations','["synthetic_only","declared_stationary_reconciliation_only","scope1_incomplete","corporate_inventory_incomplete","factor_and_method_not_released","no_emissions_aggregation","requirements_not_determined","no_external_assurance"]'::jsonb,
'synthetic',true,'scope1Completeness','incomplete','corporateCompleteness','incomplete','releaseEligible',false,'assurance','none','emissionsTotals',null);
return base||jsonb_build_object('contentSha256',neuvetra.m67_hash(base));
end $$;

create function neuvetra.m76_current_reconciliation(target_company uuid,review_override jsonb default null)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare coverage jsonb;roster jsonb;reviews jsonb;begin
select v.payload||jsonb_build_object('review',r.payload)into coverage from neuvetra.corporate_inventory_heads h join neuvetra.corporate_inventory_versions v on v.id=h.version_id and v.company_id=h.company_id left join neuvetra.corporate_inventory_reviews r on r.version_id=v.id and r.company_id=v.company_id where h.company_id=target_company;
select v.payload into roster from neuvetra.stationary_equipment_heads h join neuvetra.stationary_equipment_versions v on v.id=h.version_id and v.company_id=h.company_id where h.company_id=target_company;
select coalesce(jsonb_agg(r.payload order by r.reviewed_at,r.id),'[]')into reviews from neuvetra.stationary_equipment_reviews r where r.company_id=target_company;if review_override is not null and review_override<>'null'::jsonb then reviews:=reviews||jsonb_build_array(review_override);end if;
return neuvetra.m76_derive_reconciliation(target_company,coverage,neuvetra.m76_current_workpapers(target_company),roster,reviews);end $$;

create function neuvetra.m76_acceptance_ready(target_company uuid,version_payload jsonb)returns boolean language sql stable security definer set search_path=pg_catalog,neuvetra,pg_temp as $$select not exists(select 1 from jsonb_array_elements(neuvetra.m76_current_reconciliation(target_company)->'findings')f where f->>'blocking'='true'and f->>'code'<>'roster_review_required')$$;

create function neuvetra.m76_reconciliation_shape_valid(target_company uuid,snapshot jsonb)returns boolean language sql stable security definer set search_path=pg_catalog,neuvetra,pg_temp as $$select snapshot->>'profile'='m76-stationary-reconciliation-report-v1'and snapshot->'reconciliation'=neuvetra.m76_current_reconciliation(target_company)$$;

create function neuvetra.m76_resolved_references(activity jsonb,coverage jsonb)returns void language plpgsql immutable set search_path=pg_catalog,neuvetra as $$declare a jsonb;l jsonb;id text;begin
for a in select x from jsonb_array_elements(activity#>'{rosterStatement,assets}')x loop if a->>'entityId' is not null and not exists(select 1 from jsonb_array_elements(coverage#>'{snapshot,entities}')e where e->>'id'=a->>'entityId') or a->>'facilityId' is not null and not exists(select 1 from jsonb_array_elements(coverage#>'{snapshot,facilities}')e where e->>'id'=a->>'facilityId')then raise exception 'unresolved declared reference'using errcode='22023';end if;end loop;
for l in select x from jsonb_array_elements(activity->'links')x loop if l->>'sourceId' is not null and not exists(select 1 from jsonb_array_elements(coverage#>'{snapshot,sources}')e where e->>'id'=l->>'sourceId')then raise exception 'unresolved source reference'using errcode='22023';end if;end loop;
for id in select x from jsonb_array_elements_text(activity#>'{rosterStatement,coveredEntityIds}')x loop if not exists(select 1 from jsonb_array_elements(coverage#>'{snapshot,entities}')e where e->>'id'=id)then raise exception 'unresolved entity population'using errcode='22023';end if;end loop;
for id in select x from jsonb_array_elements_text(activity#>'{rosterStatement,coveredFacilityIds}')x loop if not exists(select 1 from jsonb_array_elements(coverage#>'{snapshot,facilities}')e where e->>'id'=id)then raise exception 'unresolved facility population'using errcode='22023';end if;end loop;end $$;

create function neuvetra.save_stationary_equipment(target_company uuid,target_roster uuid,request jsonb,version_payload jsonb,statement_payload jsonb) returns uuid language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare actor uuid:=auth.uid();head neuvetra.stationary_equipment_heads%rowtype;prior neuvetra.stationary_equipment_versions%rowtype;old neuvetra.stationary_equipment_requests%rowtype;fingerprint text;statement_id uuid;captured timestamptz;deps jsonb;activity jsonb;content jsonb;contributors jsonb;expected_statement_text text;begin
 if not neuvetra.m76_lock(target_company,true) then raise exception 'forbidden' using errcode='42501';end if;
 if not neuvetra.m76_exact_keys(request,array['profile','coverageVersionId','coverageVersionSha256','expectedDependencySha256','period','rosterStatement','manualConfirmation','links','expectedVersionId','expectedVersionSha256','correctionReason','idempotencyKey']) or not neuvetra.m76_exact_keys(version_payload,array['id','companyId','rosterId','version','previousVersionId','previousVersionSha256','createdBy','createdAt','contributorIds','correctionReason','activity','dependencies','statement','findings','inputSha256','contentSha256','versionSha256','synthetic','scope1Completeness','corporateCompleteness','releaseEligible','assurance','emissionsTotals']) or request->>'profile' is distinct from 'synthetic-stationary-equipment-v1' or request->'period' is distinct from jsonb_build_object('start','2025-01-01','endExclusive','2026-01-01') or jsonb_typeof(request->'manualConfirmation') is distinct from 'boolean' or jsonb_typeof(request->'links') is distinct from 'array' or (request->'rosterStatement'<>'null'::jsonb and jsonb_typeof(request#>'{rosterStatement,assets}') is distinct from 'array') or jsonb_array_length(request->'links')>25 or coalesce(jsonb_array_length(request#>'{rosterStatement,assets}'),0)>25 or request->>'expectedDependencySha256'!~'^[0-9a-f]{64}$' or request->>'coverageVersionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or request->>'coverageVersionSha256'!~'^[0-9a-f]{64}$' or (request->'expectedVersionId'='null'::jsonb and (request->'expectedVersionSha256'<>'null'::jsonb or request->'correctionReason'<>'null'::jsonb)) or (request->'expectedVersionId'<>'null'::jsonb and (request->>'expectedVersionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or request->>'expectedVersionSha256'!~'^[0-9a-f]{64}$' or neuvetra.m76_text_valid(request->'correctionReason',500) is not true)) then raise exception 'invalid roster request' using errcode='22023';end if;
 deps:=neuvetra.m76_current_dependencies(target_company);activity:=request-array['expectedDependencySha256','expectedVersionId','expectedVersionSha256','correctionReason','idempotencyKey'];content:=jsonb_build_object('activity',version_payload->'activity','dependencies',version_payload->'dependencies','statement',version_payload->'statement','findings',version_payload->'findings');
 if jsonb_typeof(version_payload->'version') is distinct from 'number' or version_payload->>'version'!~'^[1-9][0-9]*$' or version_payload->>'id'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or version_payload->>'rosterId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or version_payload->>'companyId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or version_payload->>'createdBy'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or version_payload->>'createdAt'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{3}Z$' or jsonb_typeof(version_payload->'contributorIds') is distinct from 'array' or neuvetra.m76_activity_valid(activity) is not true or request->>'expectedDependencySha256' is distinct from deps->>'dependencySha256' or version_payload->'dependencies' is distinct from deps or version_payload->'activity' is distinct from activity or version_payload->>'inputSha256' is distinct from neuvetra.m67_hash(activity) or version_payload->>'contentSha256' is distinct from neuvetra.m67_hash(content) or version_payload->'synthetic' is distinct from 'true'::jsonb or version_payload->>'scope1Completeness' is distinct from 'incomplete' or version_payload->>'corporateCompleteness' is distinct from 'incomplete' or version_payload->'releaseEligible' is distinct from 'false'::jsonb or version_payload->>'assurance' is distinct from 'none' or version_payload->'emissionsTotals' is distinct from 'null'::jsonb or version_payload->'findings' is distinct from neuvetra.m76_roster_findings(activity,(select cv.payload from neuvetra.corporate_inventory_heads ch join neuvetra.corporate_inventory_versions cv on cv.company_id=ch.company_id and cv.id=ch.version_id where ch.company_id=target_company)) then raise exception 'invalid roster derivation' using errcode='22023';end if;
 if request->>'coverageVersionId' is distinct from deps#>>'{coveragePin,id}' or request->>'coverageVersionSha256' is distinct from deps#>>'{coveragePin,sha256}' then raise exception 'stale roster dependencies' using errcode='23505';end if;
 perform neuvetra.m76_resolved_references(activity,(select v.payload from neuvetra.corporate_inventory_versions v where v.company_id=target_company and v.id=(activity->>'coverageVersionId')::uuid));
fingerprint:=neuvetra.m67_hash(jsonb_build_object('operation','save','actor',actor,'companyId',target_company,'rosterId',target_roster,'request',request-'idempotencyKey'));select * into old from neuvetra.stationary_equipment_requests where company_id=target_company and idempotency_key=(request->>'idempotencyKey')::uuid;if found then if old.fingerprint<>fingerprint or old.kind<>'save' or old.actor_id<>actor then raise exception 'idempotency conflict' using errcode='23505';end if;return old.record_id;end if;
 select * into head from neuvetra.stationary_equipment_heads where company_id=target_company for update;if head.id is null then if target_roster is not null or request->'expectedVersionId' is distinct from 'null'::jsonb then raise exception 'invalid first roster' using errcode='23505';end if;insert into neuvetra.stationary_equipment_heads(company_id,id) values(target_company,(version_payload->>'rosterId')::uuid) returning * into head;else if target_roster is distinct from head.id then raise exception 'roster conflict' using errcode='23505';end if;select * into prior from neuvetra.stationary_equipment_versions where company_id=target_company and id=head.version_id;if prior.id::text is distinct from request->>'expectedVersionId' or prior.version_sha256 is distinct from request->>'expectedVersionSha256' then raise exception 'stale roster' using errcode='23505';end if;if head.revision>=40 then raise exception 'roster history capacity reached' using errcode='54000';end if;if prior.id is not null and (request->'correctionReason'='null'::jsonb or prior.payload->'statement'<>'null'::jsonb and version_payload->'statement'='null'::jsonb or prior.payload->'activity'=activity and prior.payload->'dependencies'=deps or exists(select 1 from jsonb_array_elements(prior.payload#>'{activity,rosterStatement,assets}') old_asset where not exists(select 1 from jsonb_array_elements(version_payload#>'{activity,rosterStatement,assets}') new_asset where new_asset->>'rowId'=old_asset->>'rowId'))) or exists(select 1 from jsonb_array_elements(prior.payload#>'{activity,rosterStatement,assets}')oa join jsonb_array_elements(activity#>'{rosterStatement,assets}')na on na->>'rowId'=oa->>'rowId'where oa->>'equipmentId' is not null and na->>'equipmentId' is null)or exists(select 1 from jsonb_array_elements(prior.payload#>'{activity,links}')ol join jsonb_array_elements(activity->'links')nl on nl->>'rowId'=ol->>'rowId'where ol->>'sourceId' is not null and nl->>'sourceId' is null)then raise exception 'invalid roster correction' using errcode='22023';end if;end if;if octet_length(convert_to(neuvetra.m67_canonical(version_payload),'utf8'))>100000 then raise exception 'roster version too large' using errcode='22023';end if;if (select coalesce(sum(octet_length(convert_to(export_text,'utf8'))),0) from neuvetra.stationary_equipment_versions where company_id=target_company)+(select coalesce(sum(octet_length(convert_to(payload->>'html','utf8'))+octet_length(convert_to(payload->>'snapshotJson','utf8'))),0) from neuvetra.stationary_equipment_reports where company_id=target_company)+octet_length(convert_to(neuvetra.m67_canonical(version_payload),'utf8'))>3800000 then raise exception 'fleet history capacity reached' using errcode='22023';end if;select coalesce(jsonb_agg(to_jsonb(x) order by x),'[]'::jsonb) into contributors from(select distinct x from(select jsonb_array_elements_text(coalesce(prior.payload->'contributorIds','[]'::jsonb)) x union all select jsonb_array_elements_text(coalesce((select v.payload->'contributorIds' from neuvetra.corporate_inventory_heads h join neuvetra.corporate_inventory_versions v on v.id=h.version_id and v.company_id=h.company_id where h.company_id=target_company),'[]'::jsonb)) union all select jsonb_array_elements_text(v.payload->'contributorIds') from neuvetra.stationary_gas_heads h join neuvetra.stationary_gas_versions v on v.id=h.version_id and v.company_id=h.company_id where h.company_id=target_company union all select jsonb_array_elements_text(v.payload->'contributorIds')from neuvetra.stationary_diesel_heads h join neuvetra.stationary_diesel_versions v on v.id=h.version_id and v.company_id=h.company_id where h.company_id=target_company union all select actor::text) q) s;
 if version_payload->>'companyId' is distinct from target_company::text or version_payload->>'rosterId' is distinct from head.id::text or version_payload->>'createdBy' is distinct from actor::text or (version_payload->>'version')::integer is distinct from head.revision+1 or version_payload->'previousVersionId' is distinct from coalesce(to_jsonb(prior.id),'null'::jsonb) or version_payload->'previousVersionSha256' is distinct from coalesce(to_jsonb(prior.version_sha256),'null'::jsonb) or version_payload->'correctionReason' is distinct from request->'correctionReason' or version_payload->'contributorIds' is distinct from contributors or version_payload->>'versionSha256' is distinct from neuvetra.m67_hash(jsonb_build_object('profile','synthetic-stationary-equipment-v1','id',version_payload->'id','companyId',version_payload->'companyId','rosterId',version_payload->'rosterId','version',version_payload->'version','previousVersionId',version_payload->'previousVersionId','previousVersionSha256',version_payload->'previousVersionSha256','createdBy',version_payload->'createdBy','createdAt',version_payload->'createdAt','contributorIds',version_payload->'contributorIds','correctionReason',version_payload->'correctionReason','inputSha256',version_payload->'inputSha256','contentSha256',version_payload->'contentSha256')) then raise exception 'invalid roster payload' using errcode='22023';end if;
 captured:=(version_payload->>'createdAt')::timestamptz;if version_payload->'statement' is distinct from 'null'::jsonb::jsonb then expected_statement_text:='SYNTHETIC — NOT AN ORIGINAL COMPANY EQUIPMENT REGISTER OR INDEPENDENT MEASUREMENT'||chr(10)||neuvetra.m67_canonical(jsonb_build_object('profile','m76-synthetic-equipment-statement-v1','companyLabel',(select cv.payload#>>'{snapshot,companyLabel}' from neuvetra.corporate_inventory_versions cv where cv.company_id=target_company and cv.id=(activity->>'coverageVersionId')::uuid),'coverageVersionId',activity->'coverageVersionId','coverageVersionSha256',activity->'coverageVersionSha256','period',activity->'period','statement',activity->'rosterStatement'))||chr(10);if not neuvetra.m76_exact_keys(version_payload->'statement',array['id','profile','input','locator','text','sha256','byteLength']) or version_payload#>>'{statement,profile}' is distinct from 'm76-synthetic-equipment-statement-v1' or version_payload#>'{statement,input}' is distinct from activity->'rosterStatement' or version_payload#>>'{statement,locator}' is distinct from 'm76-equipment-statement:'||(version_payload#>>'{statement,id}')||':declared-equipment' or version_payload#>>'{statement,text}' is distinct from expected_statement_text or version_payload#>>'{statement,sha256}' is distinct from encode(sha256(convert_to(expected_statement_text,'utf8')),'hex') or (version_payload#>>'{statement,byteLength}')::integer is distinct from octet_length(convert_to(expected_statement_text,'utf8')) then raise exception 'invalid roster statement derivation' using errcode='22023';end if;end if;if statement_payload is distinct from 'null'::jsonb then statement_id:=(statement_payload->>'id')::uuid;if statement_payload is distinct from version_payload->'statement' or statement_payload->>'sha256' is distinct from encode(sha256(convert_to(statement_payload->>'text','utf8')),'hex') or (statement_payload->>'byteLength')::integer is distinct from octet_length(convert_to(statement_payload->>'text','utf8')) then raise exception 'invalid statement' using errcode='22023';end if;insert into neuvetra.stationary_equipment_statements values(statement_id,target_company,statement_payload,statement_payload->>'sha256',statement_payload->>'text');elsif version_payload->'statement' is distinct from 'null'::jsonb then statement_id:=(version_payload#>>'{statement,id}')::uuid;perform 1 from neuvetra.stationary_equipment_statements where company_id=target_company and id=statement_id and payload=version_payload->'statement';if not found then raise exception 'missing retained statement' using errcode='22023';end if;end if;
 insert into neuvetra.stationary_equipment_versions values((version_payload->>'id')::uuid,target_company,head.id,(version_payload->>'version')::integer,nullif(version_payload->>'previousVersionId','')::uuid,(version_payload#>>'{activity,coverageVersionId}')::uuid,statement_id,version_payload,version_payload->>'inputSha256',version_payload->>'contentSha256',version_payload->>'versionSha256',actor,captured,neuvetra.m67_canonical(version_payload));update neuvetra.stationary_equipment_heads set version_id=(version_payload->>'id')::uuid,revision=revision+1 where company_id=target_company;
 insert into neuvetra.stationary_equipment_requests values(target_company,(request->>'idempotencyKey')::uuid,actor,'save',fingerprint,(version_payload->>'id')::uuid);insert into neuvetra.stationary_equipment_audit values(gen_random_uuid(),target_company,(version_payload->>'id')::uuid,'save',version_payload->>'versionSha256',actor,captured);return (version_payload->>'id')::uuid;end $$;

create function neuvetra.review_stationary_equipment(target_company uuid,target_roster uuid,request jsonb,review_payload jsonb) returns uuid language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare actor uuid:=auth.uid();v record;old record;fingerprint text;deps jsonb;begin if not neuvetra.m76_lock(target_company,true) then raise exception 'forbidden' using errcode='42501';end if;if not neuvetra.m76_exact_keys(request,array['versionId','expectedVersionSha256','expectedDependencySha256','decision','note','acknowledgedLimitations','idempotencyKey']) or not neuvetra.m76_exact_keys(review_payload,array['id','versionId','versionSha256','dependencies','decision','note','acknowledgedLimitations','reviewerId','reviewedAt','decisionSha256']) or request->>'versionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or request->>'expectedVersionSha256'!~'^[0-9a-f]{64}$' or request->>'expectedDependencySha256'!~'^[0-9a-f]{64}$' or request->>'idempotencyKey'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or review_payload->>'id'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or review_payload->>'reviewerId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or review_payload->>'reviewedAt'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{3}Z$' or review_payload->>'decisionSha256'!~'^[0-9a-f]{64}$' or request->>'decision' is null or request->>'decision' not in('accepted_bounded_reconciliation','changes_requested') or neuvetra.m76_text_valid(request->'note',500) is not true or request->'acknowledgedLimitations' is distinct from '["synthetic_only","declared_stationary_reconciliation_only","scope1_incomplete","corporate_inventory_incomplete","factor_and_method_not_released","no_emissions_aggregation","requirements_not_determined","no_external_assurance"]'::jsonb then raise exception 'invalid review request' using errcode='22023';end if;deps:=neuvetra.m76_current_dependencies(target_company);if request->>'expectedDependencySha256' is distinct from deps->>'dependencySha256' then raise exception 'review dependencies changed' using errcode='23505';end if;fingerprint:=neuvetra.m67_hash(jsonb_build_object('operation','review','actor',actor,'companyId',target_company,'rosterId',target_roster,'request',request-'idempotencyKey'));select * into old from neuvetra.stationary_equipment_requests where company_id=target_company and idempotency_key=(request->>'idempotencyKey')::uuid;if found then if old.fingerprint<>fingerprint or old.kind<>'review' or old.actor_id<>actor then raise exception 'idempotency conflict' using errcode='23505';end if;return old.record_id;end if;select vv.* into v from neuvetra.stationary_equipment_heads h join neuvetra.stationary_equipment_versions vv on vv.company_id=h.company_id and vv.id=h.version_id where h.company_id=target_company and h.id=target_roster and vv.id=(request->>'versionId')::uuid;if not found or v.version_sha256 is distinct from request->>'expectedVersionSha256' then raise exception 'review conflict' using errcode='23505';end if;if exists(select 1 from jsonb_array_elements_text(v.payload->'contributorIds')x where x=actor::text) then raise exception 'contributors cannot review' using errcode='42501';end if;if request->>'decision'='accepted_bounded_reconciliation' and (neuvetra.m76_current_reconciliation(target_company,review_payload)#>>'{status}') is distinct from 'reconciled_bounded_synthetic' then raise exception 'blocked reconciliation cannot be accepted' using errcode='22023';end if;if review_payload->>'reviewerId' is distinct from actor::text or review_payload->>'versionId' is distinct from v.id::text or review_payload->>'versionSha256' is distinct from v.version_sha256 or review_payload->'dependencies' is distinct from deps or v.payload->'dependencies' is distinct from deps or review_payload->'decision' is distinct from request->'decision' or review_payload->'note' is distinct from request->'note' or review_payload->'acknowledgedLimitations' is distinct from request->'acknowledgedLimitations' or review_payload->>'decisionSha256' is distinct from neuvetra.m67_hash((review_payload-'decisionSha256')||jsonb_build_object('profile','synthetic-stationary-equipment-v1','companyId',target_company)) then raise exception 'invalid review' using errcode='22023';end if;insert into neuvetra.stationary_equipment_reviews values((review_payload->>'id')::uuid,target_company,v.id,review_payload,review_payload->>'decisionSha256',actor,(review_payload->>'reviewedAt')::timestamptz);insert into neuvetra.stationary_equipment_requests values(target_company,(request->>'idempotencyKey')::uuid,actor,'review',fingerprint,(review_payload->>'id')::uuid);insert into neuvetra.stationary_equipment_audit values(gen_random_uuid(),target_company,(review_payload->>'id')::uuid,'review',review_payload->>'decisionSha256',actor,(review_payload->>'reviewedAt')::timestamptz);return (review_payload->>'id')::uuid;end $$;

create function neuvetra.create_stationary_equipment_report(target_company uuid,target_roster uuid,request jsonb,report_payload jsonb) returns uuid language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare actor uuid:=auth.uid();old record;fingerprint text;v record;r record;snapshot jsonb;body jsonb;ready boolean;begin if not neuvetra.m76_lock(target_company,true) then raise exception 'forbidden' using errcode='42501';end if;if not neuvetra.m76_exact_keys(request,array['expectedReconciliationSha256','idempotencyKey']) or not neuvetra.m76_exact_keys(report_payload,array['id','companyId','rosterId','rosterVersionId','createdBy','createdAt','rendererVersion','snapshotJson','snapshotSha256','html','htmlSha256','htmlByteLength','reportSha256']) or request->>'expectedReconciliationSha256'!~'^[0-9a-f]{64}$' or request->>'idempotencyKey'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or report_payload->>'id'!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or report_payload->>'createdAt'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{3}Z$' or jsonb_typeof(report_payload->'snapshotJson') is distinct from 'string' or jsonb_typeof(report_payload->'html') is distinct from 'string' or jsonb_typeof(report_payload->'htmlByteLength') is distinct from 'number' or report_payload->>'htmlByteLength'!~'^[0-9]+$' then raise exception 'invalid report request' using errcode='22023';end if;fingerprint:=neuvetra.m67_hash(jsonb_build_object('operation','report','actor',actor,'companyId',target_company,'rosterId',target_roster,'request',request-'idempotencyKey'));select * into old from neuvetra.stationary_equipment_requests where company_id=target_company and idempotency_key=(request->>'idempotencyKey')::uuid;if found then if old.fingerprint<>fingerprint or old.kind<>'report' or old.actor_id<>actor then raise exception 'idempotency conflict' using errcode='23505';end if;return old.record_id;end if;select vv.* into v from neuvetra.stationary_equipment_heads h join neuvetra.stationary_equipment_versions vv on vv.company_id=h.company_id and vv.id=h.version_id where h.company_id=target_company and h.id=target_roster; if not found then raise exception 'report roster changed' using errcode='23505';end if;if (select count(*) from neuvetra.stationary_equipment_reports where company_id=target_company)>=40 or octet_length(convert_to(report_payload->>'html','utf8'))>131072 then raise exception 'report capacity reached' using errcode='54000';end if;if (select coalesce(sum(octet_length(convert_to(export_text,'utf8'))),0) from neuvetra.stationary_equipment_versions where company_id=target_company)+(select coalesce(sum(octet_length(convert_to(payload->>'html','utf8'))+octet_length(convert_to(payload->>'snapshotJson','utf8'))),0) from neuvetra.stationary_equipment_reports where company_id=target_company)+octet_length(convert_to(report_payload->>'html','utf8'))+octet_length(convert_to(report_payload->>'snapshotJson','utf8'))>3800000 then raise exception 'fleet history capacity reached' using errcode='22023';end if;select rr.payload into r from neuvetra.stationary_equipment_reviews rr where rr.company_id=target_company and rr.version_id=v.id and rr.payload#>>'{dependencies,dependencySha256}'=(neuvetra.m76_current_dependencies(target_company)->>'dependencySha256');snapshot:=(report_payload->>'snapshotJson')::jsonb;ready:=neuvetra.m76_acceptance_ready(target_company,v.payload) and r.payload->>'decision'='accepted_bounded_reconciliation';body:=jsonb_build_object('profile','synthetic-stationary-equipment-v1','id',report_payload->'id','companyId',report_payload->'companyId','rosterId',report_payload->'rosterId','rosterVersionId',report_payload->'rosterVersionId','createdBy',report_payload->'createdBy','createdAt',report_payload->'createdAt','rendererVersion',report_payload->'rendererVersion','snapshotSha256',report_payload->'snapshotSha256','htmlSha256',report_payload->'htmlSha256','htmlByteLength',report_payload->'htmlByteLength');if report_payload->>'companyId' is distinct from target_company::text or report_payload->>'rosterId' is distinct from target_roster::text or report_payload->>'rosterVersionId' is distinct from v.id::text or report_payload->>'createdBy' is distinct from actor::text or report_payload->>'rendererVersion' is distinct from 'm76-stationary-reconciliation-report-v1' or snapshot->'reconciliation' is distinct from neuvetra.m76_current_reconciliation(target_company) or neuvetra.m76_reconciliation_shape_valid(target_company,snapshot) is not true or report_payload->>'html' is distinct from neuvetra.m76_render_report(snapshot) or report_payload->>'htmlSha256' is distinct from encode(sha256(convert_to(report_payload->>'html','utf8')),'hex') or report_payload->>'snapshotSha256' is distinct from encode(sha256(convert_to(report_payload->>'snapshotJson','utf8')),'hex') or (report_payload->>'htmlByteLength')::integer is distinct from octet_length(convert_to(report_payload->>'html','utf8')) or report_payload->>'reportSha256' is distinct from neuvetra.m67_hash(body) or neuvetra.m67_canonical(snapshot) is distinct from report_payload->>'snapshotJson' or snapshot->'version' is distinct from v.payload or snapshot->'review' is distinct from coalesce(r.payload,'null'::jsonb) or snapshot#>>'{reconciliation,contentSha256}' is distinct from request->>'expectedReconciliationSha256' or snapshot#>>'{reconciliation,dependencySha256}' is distinct from (neuvetra.m76_current_dependencies(target_company)->>'dependencySha256') or snapshot#>>'{reconciliation,status}' is distinct from (case when ready then 'reconciled_bounded_synthetic' else 'blocked' end) then raise exception 'invalid report' using errcode='22023';end if;insert into neuvetra.stationary_equipment_reports values((report_payload->>'id')::uuid,target_company,target_roster,v.id,report_payload,report_payload->>'reportSha256',actor,(report_payload->>'createdAt')::timestamptz);insert into neuvetra.stationary_equipment_requests values(target_company,(request->>'idempotencyKey')::uuid,actor,'report',fingerprint,(report_payload->>'id')::uuid);insert into neuvetra.stationary_equipment_audit values(gen_random_uuid(),target_company,(report_payload->>'id')::uuid,'report',report_payload->>'reportSha256',actor,(report_payload->>'createdAt')::timestamptz);return (report_payload->>'id')::uuid;end $$;

create function neuvetra.m76_mobile_fuel_evidence_guard() returns trigger language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$begin
if new.statement_kind='fuel' and exists(select 1 from neuvetra.stationary_diesel_evidence_reservations r where r.company_id=new.company_id and r.kind='reference' and r.evidence_key=new.evidence_key) then raise exception 'consumed evidence conflict' using errcode='23505';end if;return new;end $$;
create trigger m76_mobile_fuel_evidence_guard before insert on neuvetra.mobile_diesel_evidence_reservations for each row execute function neuvetra.m76_mobile_fuel_evidence_guard();

do $$declare p record;begin for p in select oid::regprocedure signature,proname from pg_proc where pronamespace='neuvetra'::regnamespace and (proname like 'm76\_%' escape '\' or proname in('save_stationary_diesel','review_stationary_diesel','create_stationary_diesel_report','save_stationary_equipment','review_stationary_equipment','create_stationary_equipment_report')) loop
execute format('revoke all on function %s from public,authenticated,neuvetra_runtime',p.signature);
if p.proname in('m76_lock','m76_diesel_lock','save_stationary_diesel','review_stationary_diesel','create_stationary_diesel_report','save_stationary_equipment','review_stationary_equipment','create_stationary_equipment_report') then execute format('grant execute on function %s to neuvetra_runtime',p.signature);end if;end loop;end $$;
